		text_id = "#C0x5C9971#%s#C0x5B545B#dikelilingi dalam %s element room oleh #C0xE77421#%s#C0x5B545B#! Cepat, tawarkan bantuan pada mereka#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_kr = "#C0x5C9971#%s#C0x5B545B#은 #C0xE77421#%s#C0x5B545B#에 의해 %s 요소 방에 둘러싸여 있습니다! 서둘러서 도움을 주세요#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_th = "#C0x5C9971#%s#C0x5B545B#กำลังถูกล้อมรอบอยู่ในห้ององค์ประกอบ %s โดย #C0xE77421#%s#C0x5B545B#! รีบให้ความช่วยเหลือพวกเขาหน่อย#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_es = "¡#C0x5C9971#%s#C0x5B545B#está rodeado en la sala del elemento %s por #C0xE77421#%s#C0x5B545B#! Date prisa, ofréceles ayuda#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text = "#C0x5C9971#%s#C0x5B545B#is being surrounded in the %s element room by #C0xE77421#%s#C0x5B545B#! Hurry, offer them some assistance#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		id = 1001
	},
