	[1009] = {
		text_en = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for getting #C0xE69900#{amount}{gainType}({rate}x Golden Egg rewards) in the Golden Egg event!#C0x5B545B#",
		key = "NewsBreakEgg",
		text_vn = "#C0x5B545B#Parabéns a #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# por obter #C0xE69900#{amount}{gainType}({rate}x recompensas Golden Egg) no evento Golden Egg!#C0x5B545B#",
		text_id = "#C0x5B545B#Selamat kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# karena telah mendapatkan #C0xE69900#{amount}{gainType}({rate}x hadiah Telur Emas) di Event Telur Emas!#C0x5B545B#",
		text_kr = "#C0x5B545B#황금알 이벤트에서 #C0x5C9971##L10100##LULrole1#({name}x 황금알 보상)을 획득한 #C0x5B545B##C0xE69900#{amount}{gainType}{rate}을 축하합니다!#C0x5B545B#",
		text_th = "#C0x5B545B#ขอแสดงความยินดีกับ #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# ที่ได้รับ #C0xE69900#{amount}{gainType}({rate}x รางวัลไข่ทองคำ) ในกิจกรรมไข่ทองคำ!#C0x5B545B#",
		text_es = "#C0x5B545B#¡Felicitaciones a #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# por obtener #C0xE69900#{amount}{gainType}({rate}x recompensas de Huevo de Oro) en el evento Huevo de Oro!#C0x5B545B#",
		text = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for getting #C0xE69900#{amount}{gainType}({rate}x Golden Egg rewards) in the Golden Egg event!#C0x5B545B#",
		id = 1009
	},
	[1010] = {
		text_en = "#C0x5B545B#Congratulations! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# gets rare held item #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B# from Trinket Card Draw, lady luck is smiling!",
		key = "NewsHoldItemInDraw",
