	[1028] = {
		text_en = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for achieving top in the Arena with an unparalleled strength! It's probably true that it can be kinda lonely at the top...",
		key = "NewsPVPTopRank",
		text_vn = "#C0x5B545B#Parabéns a #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# por alcançar o topo na Arena com uma força incomparável! Provavelmente é verdade que pode ser um pouco solitário no topo...",
		text_id = "#C0x5B545B#Selamat kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# karena telah mencapai TOP di Arena dengan kekuatan tak tertandingi! mungkin benar bahwa di puncak bisa terasa sepi...",
		text_kr = "#C0x5B545B#탁월한 체력으로 아레나에서 정상에 오른 #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# 축하드립니다! 정상에 오르면 좀 외로울 수도 있다는 게 사실일 수도 있겠네요...",
		text_th = "#C0x5B545B#ขอแสดงความยินดีกับ #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# สำหรับการบรรลุเป้าหมายในอารีน่าด้วยความแข็งแกร่งที่ไม่มีใครเทียบได้! มันอาจจะจริงที่ด้านบนมันก็เหงาได้นะ...",
		text_es = "#C0x5B545B#Felicitaciones a #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# por alcanzar la cima en la Arena con una fuerza incomparable. Probablemente sea cierto que puede resultar un poco solitario estar en la cima...",
		text = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for achieving top in the Arena with an unparalleled strength! It's probably true that it can be kinda lonely at the top...",
		id = 1028
	},
	[1029] = {
		text_en = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# who reaches trial floor 40 after going through lots of difficulties! We hope you reach greater heights in the future!",
		key = "NewsYZPassFloor40",
		text_vn = "#C0x5B545B#Parabéns para #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# que chega ao nível de prova 40 depois de passar por muitas dificuldades! Esperamos que você alcance maiores alturas no futuro!",
		text_id = "#C0x5B545B#Selamat kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang mencapai lantai Trial 40 setelah melalui banyak kesulitan! Kami harap Anda mencapai Level yang lebih tinggi di masa depan!",
		text_kr = "#C0x5B545B#많은 어려움을 겪고 트라이얼 40층에 도달한 #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# 축하드립니다! 앞으로 더 높은 곳에 도달하길 바랍니다!",
		text_th = "#C0x5B545B#ขอแสดงความยินดีกับ #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# ที่มาถึงชั้นทดลอง 40 หลังจากผ่านความยากลำบากมามากมาย! เราหวังว่าคุณจะบรรลุจุดสูงสุดในอนาคต!",
		text_es = "#C0x5B545B#¡Felicitaciones a #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# que llega al piso de prueba 40 después de pasar por muchas dificultades! ¡Esperamos que alcance mayores alturas en el futuro!",
		text = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# who reaches trial floor 40 after going through lots of difficulties! We hope you reach greater heights in the future!",
		id = 1029
	},
	[1030] = {
		text_en = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# who reaches trial floor 50 after going through lots of difficulties! Do keep up the good work and reach greater heights in the future!",
		key = "NewsYZPassFloor50",
		text_vn = "#C0x5B545B#Parabéns para #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# que chega ao andar de prova 50 depois de passar por muitas dificuldades! Continue com o bom trabalho e alcance maiores alturas no futuro!",
		text_id = "#C0x5B545B#Selamat kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang mencapai lantai Trial 50 setelah melalui banyak kesulitan! Teruslah bekerja dengan baik dan raih Level yang lebih tinggi di masa depan!",
		text_kr = "#C0x5B545B#많은 어려움을 겪고 트라이얼 50층에 도달한 #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# 축하드립니다! 앞으로도 계속 좋은 일을 하셔서 더 높은 곳으로 올라가세요!",
		text_th = "#C0x5B545B#ขอแสดงความยินดีกับ #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# ที่มาถึงชั้นทดลองที่ 50 หลังจากผ่านความยากลำบากมามากมาย! ติดตามการทำงานที่ดีและก้าวไปสู่จุดสูงสุดในอนาคต!",
		text_es = "#C0x5B545B#¡Felicitaciones a #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# que llega al piso de prueba 50 después de pasar por muchas dificultades! ¡Sigue con el buen trabajo y alcanza mayores alturas en el futuro!",
		text = "#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# who reaches trial floor 50 after going through lots of difficulties! Do keep up the good work and reach greater heights in the future!",
		id = 1030
	},
	[1031] = {
