	[1050] = {
		text_en = "#C0x5B545B#As you've displayed a heroic performance yesterday, you may skip this floor's battle and get full stars with the highest points. Continue? (You can only skip %s floors at most today)",
		key = "pass_battle",
		text_vn = "#C0x5B545B#Como você exibiu um desempenho heróico ontem, você pode pular a batalha deste andar e obter estrelas completas com os pontos mais altos. Continuar? (Você só pode pular no máximo %s andares hoje)",
		text_id = "#C0x5B545B#Saat ka anda menunjukkan performa heroik kemarin, ka anda bisa melewati pertarungan lantai ini dan mendapatkan bintang penuh dengan poin tertinggi. Melanjutkan? (Anda hanya dapat melewati paling banyak %s lantai hari ini)",
		text_kr = "#C0x5B545B#어제 영웅적인 활약을 펼쳤으므로 이 층의 전투를 생략하고 가장 높은 점수로 풀스타를 획득하실 수 있습니다. 계속하다? (오늘은 최대 %s개 층만 건너뛸 수 있습니다.)",
		text_th = "#C0x5B545B#เมื่อวานคุณได้แสดงท่าทีกล้าหาญ คุณอาจข้ามการต่อสู้ของชั้นนี้และรับดาวเต็มที่มีคะแนนสูงสุดได้ ดำเนินการต่อ? (คุณสามารถข้ามได้สูงสุดเพียง %s ชั้นในวันนี้)",
		text_es = "#C0x5B545B# Como ayer demostraste una actuación heroica, puedes saltarte la batalla de este piso y obtener estrellas completas con los puntos más altos. ¿Continuar? (Hoy solo puedes saltarte %s pisos como máximo)",
		text = "#C0x5B545B#As you've displayed a heroic performance yesterday, you may skip this floor's battle and get full stars with the highest points. Continue? (You can only skip %s floors at most today)",
		id = 1050
	},
