	[1063] = {
		text_en = "#C0x5B545B#I'm fighting against  #C0x5C9971#{enemy}#C0x5B545B# at #C0xF13B54#{where}#C0x5B545B#. It'll be an exciting battle and I welcome all to spectate the battle.#LULbattleID##Icommon/btn/img_ckxq.png-182-54#",
		key = "battleShare",
		text_vn = "#C0x5B545B#Estou lutando contra #C0x5C9971#{enemy}#C0x5B545B# em #C0xF13B54#{where}#C0x5B545B#. Será uma batalha emocionante e dou as boas-vindas a todos para assistir à batalha.#LULbattleID##Icommon/btn/img_ckxq.png-182-54#",
		text_id = "#C0x5B545B#Aku bertarung melawan #C0x5C9971#{enemy}#C0x5B545B# di #C0xF13B54#{where}#C0x5B545B#. Ini akan menjadi pertarungan yang seru dan saya menyambut semua orang untuk menyaksikan pertarungan tersebut.#LULbattleID##Icommon/btn/img_ckxq.png-182-54#",
		text_kr = "#C0x5B545B#나는 #C0x5C9971#{enemy}#C0x5B545B#에서 #C0xF13B54#{where}#C0x5B545B#과 싸우고 있습니다. 흥미진진한 전투가 될 테니 모두들 관전해 주시길 바랍니다#LULbattleID##Icommon/btn/img_ckxq.png-182-54#",
		text_th = "#C0x5B545B#ฉันกำลังสู้กับ #C0x5C9971#{enemy}#C0x5B545B# ที่ #C0xF13B54#{where}#C0x5B545B#. มันจะเป็นการต่อสู้ที่น่าตื่นเต้น และฉันยินดีต้อนรับทุกท่านที่ชมการต่อสู้#LULbattleID##Icommon/btn/img_ckxq.png-182-54#",
		text_es = "#C0x5B545B#Estoy peleando contra #C0x5C9971#{enemy}#C0x5B545B# en #C0xF13B54#{where}#C0x5B545B#. Será una batalla emocionante y doy la bienvenida a todos a presenciar la batalla. #LULbattleID##Icommon/btn/img_ckxq.png-182-54#",
		text = "#C0x5B545B#I'm fighting against  #C0x5C9971#{enemy}#C0x5B545B# at #C0xF13B54#{where}#C0x5B545B#. It'll be an exciting battle and I welcome all to spectate the battle.#LULbattleID##Icommon/btn/img_ckxq.png-182-54#",
		id = 1063
	},
	[1064] = {
		text_en = "#C0x5B545B#The union#C0x5C9971##L10100##LULunion1#{name}#C0x5B545B#is recruiting: #C0xE77421#{desc}#LULunion1##Icommon/btn/img_ckxq.png-182-54#",
		key = "unionJoinupInvite",
		text_vn = "#C0x5B545B#O sindicato#C0x5C9971##L10100##LULunion1#{name}#C0x5B545B#está recrutando: #C0xE77421#{desc}#LULunion1##Icommon/btn/img_ckxq.png-182-54#",
		text_id = "#C0x5B545B#Serikat #C0x5C9971##L10100##LULunion1#{name}#C0x5B545B#sedang merekrut: #C0xE77421#{desc}#LULunion1##Icommon/btn/img_ckxq.png-182-54#",
		text_kr = "#C0x5B545B#노조#C0x5C9971##L10100##LULunion1#{name}#C0x5B545B#모집 중: #C0xE77421#{desc}#LULunion1##Icommon/btn/img_ckxq.png-182-54#",
		text_th = "#C0x5B545B#สหภาพแรงงาน#C0x5C9971##L10100##LULunion1#{name}#C0x5B545B#กำลังรับสมัคร: #C0xE77421#{desc}#LULunion1##Icommon/btn/img_ckxq.png-182-54#",
		text_es = "#C0x5B545B#El sindicato#C0x5C9971##L10100##LULunion1#{name}#C0x5B545B#está reclutando: #C0xE77421#{desc}#LULunion1##Icommon/btn/img_ckxq.png-182-54#",
