	[1065] = {
		text_en = "We welcome everyone to join us.",
		key = "unionJoinupDesc",
		text_vn = "Damos as boas-vindas a todos para se juntarem a nós.",
		text_id = "Kami menyambut semua orang untuk bergabung dengan kami.",
		text_kr = "우리와 함께하는 모든 사람을 환영합니다.",
		text_th = "เรายินดีต้อนรับทุกคนที่จะเข้าร่วมกับเรา",
		text_es = "Damos la bienvenida a todos a unirse a nosotros.",
		text = "We welcome everyone to join us.",
		id = 1065
	},
	[1066] = {
		text_en = "#C0x5B545B#My #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# is really awesome, come and check it out!#LULcard1##Icommon/btn/img_ckxq.png-182-54#",
		key = "NewsCardShare",
		text_vn = "#C0x5B545B#Meu #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# é realmente incrível, venha conferir!#LULcard1##Icommon/btn/img_ckxq.png-182-54#",
		text_id = "#C0x5B545B# #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# milikku sungguh luar biasa, datang dan lihatlah!#LULcard1##Icommon/btn/img_ckxq.png-182-54#",
		text_kr = "#C0x5B545B#내 #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# 정말 대단해요, 와서 확인해보세요!#LULcard1##Icommon/btn/img_ckxq.png-182-54#",
		text_th = "#C0x5B545B#My #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# สุดยอดจริงๆ มาลองดูสิ!#LULcard1##Icommon/btn/img_ckxq.png-182-54#",
		text_es = "#C0x5B545B#Mi #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# es realmente increíble, ¡ven y compruébalo! #LULcard1##Icommon/btn/img_ckxq.png-182-54#",
		text = "#C0x5B545B#My #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# is really awesome, come and check it out!#LULcard1##Icommon/btn/img_ckxq.png-182-54#",
		id = 1066
	},
	[1068] = {
		text_en = "#C0x5C9971#%s#C0x5B545B#is being surrounded in the %s element room by #C0xE77421#%s#C0x5B545B#! Hurry, offer them some assistance#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		key = "FriendCloneInvite",
		text_vn = "#C0x5C9971#%s#C0x5B545B#está sendo cercado na sala do elemento %s por #C0xE77421#%s#C0x5B545B#! Depressa, ofereça-lhes alguma ajuda#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_id = "#C0x5C9971#%s#C0x5B545B#dikelilingi dalam %s ruang elemen oleh #C0xE77421#%s#C0x5B545B#! Cepat, tawarkan bantuan pada mereka#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_kr = "#C0x5C9971#%s#C0x5B545B#은 #C0xE77421#%s#C0x5B545B#에 의해 %s 요소 방에 둘러싸여 있습니다! 서둘러서 도움을 주세요#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_th = "#C0x5C9971#%s#C0x5B545B#กำลังถูกล้อมรอบอยู่ในห้ององค์ประกอบ %s โดย #C0xE77421#%s#C0x5B545B#! รีบให้ความช่วยเหลือพวกเขาหน่อย#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_es = "¡#C0x5C9971#%s#C0x5B545B#está rodeado en la sala del elemento %s por #C0xE77421#%s#C0x5B545B#! Date prisa, ofréceles ayuda#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text = "#C0x5C9971#%s#C0x5B545B#is being surrounded in the %s element room by #C0xE77421#%s#C0x5B545B#! Hurry, offer them some assistance#LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		id = 1068
	},
