	[1070] = {
		text_en = "#C0x5B545B#Congratulations! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#gets #C0xE69900#{star}#C0x5B545B# -star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# by limited card draw and has increased its strength greatly!",
		key = "NewsCardInLimitDrawUp",
		text_vn = "#C0x5B545B#Parabéns! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#obtém #C0xE69900#{star}#C0x5B545B# -estrela #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# por sorteio limitado de cartas e aumentou seu força muito!",
		text_id = "#C0x5B545B#Selamat! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#mendapat #C0xE69900#{star}#C0x5B545B# -bintang #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# dengan penarikan kartu terbatas dan telah meningkatkan kekuatan dengan sangat kuat!",
		text_kr = "#C0x5B545B#축하해요! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#gets #C0xE69900#{star}#C0x5B545B# -star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# 제한된 카드 추첨으로 그 수가 늘어났습니다. 힘이 많이 나요!",
		text_th = "#C0x5B545B#ยินดีด้วย! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#gets #C0xE69900#{star}#C0x5B545B# -star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# ด้วยการจั่วการ์ดแบบจำกัด และได้เพิ่มขึ้น แข็งแกร่งมาก!",
		text_es = "#C0x5B545B#¡Felicidades! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#obtiene #C0xE69900#{star}#C0x5B545B# -estrella #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# por sorteo de cartas limitado y ha aumentado su ¡Fuerza enormemente!",
		text = "#C0x5B545B#Congratulations! #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#gets #C0xE69900#{star}#C0x5B545B# -star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# by limited card draw and has increased its strength greatly!",
		id = 1070
	},
	[1071] = {
		text_en = "#C0x5C9971#{role_name}#C0x5B545B# sent a #C0xF13D56#Spring Festival Red Packet#C0x5B545B# with their well wishes message#C0x8DB1D3#a #C0x5B545B#:{message}.#LULhd_redPacket_idx##Iactivity/chinese_new_year/btn_lqhb.png-182-54#",
		key = "HuoDongRedPacket",
		text_vn = "#C0x5C9971#{role_name}#C0x5B545B# enviou um #C0xF13D56#Pacote Vermelho do Festival da Primavera#C0x5B545B# com sua mensagem de felicidades#C0x8DB1D3#a #C0x5B545B#:{message}.#LULhd_redPacket_idx##Iactivity/chinese_new_year/btn_lqhb.png-182-54#",
		text_id = "#C0x5C9971#{role_name}#C0x5B545B# mengirimkan #C0xF13D56#Spring Festival Red Packet #C0x5B545B# disertai pesan ucapan selamat#C0x8DB1D3#a #C0x5B545B#:{message}.#LULhd_redPacket_idx##Iactivity/chinese_new_year/btn_lqhb.png-182-54#",
		text_kr = "#C0x5C9971#{role_name}#C0x5B545B# #C0xF13D56#춘절 레드패킷#C0x5B545B#에 행복을 기원하는 메시지를 보냈습니다#C0x8DB1D3#a #C0x5B545B#:{message}.#LULhd_redPacket_idx##Iactivity/chinese_new_year/btn_lqhb.png-182-54#",
		text_th = "#C0x5C9971#{role_name}#C0x5B545B# ส่ง #C0xF13D56#อั่งเปาเทศกาลฤดูใบไม้ผลิ#C0x5B545B# พร้อมข้อความอวยพร#C0x8DB1D3#a #C0x5B545B#:{message}.#LULhd_redPacket_idx##Iactivity/chinese_new_year/btn_lqhb.png-182-54#",
		text_es = "#C0x5C9971#{role_name}#C0x5B545B# envió un #C0xF13D56#Paquete Rojo del Festival de Primavera#C0x5B545B# con su mensaje de buenos deseos#C0x8DB1D3#a #C0x5B545B#:{message}.#LULhd_redPacket_idx##Iactivity/chinese_new_year/btn_lqhb.png-182-54#",
		text = "#C0x5C9971#{role_name}#C0x5B545B# sent a #C0xF13D56#Spring Festival Red Packet#C0x5B545B# with their well wishes message#C0x8DB1D3#a #C0x5B545B#:{message}.#LULhd_redPacket_idx##Iactivity/chinese_new_year/btn_lqhb.png-182-54#",
		id = 1071
	},
