	[1099] = {
		text_en = "#C0x5B545B#Long time no see! I'm #C0x5C9971#{name}.#C0x5B545B# Accept my invitation and help me complete the tasks! You will get rich rewards!#LULreunion##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		key = "ReunionInvite",
		text_vn = "#C0x5B545B#Faz tempo que não nos vemos! Eu sou #C0x5C9971#{name}.#C0x5B545B# Aceite meu convite e me ajude a completar as tarefas! Você receberá recompensas ricas!#LULreunion##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_id = "#C0x5B545B#Lama tidak bertemu! Saya #C0x5C9971#{name}.#C0x5B545B# Terima undangan saya dan bantu saya menyelesaikan tugas! Anda akan mendapat banyak imbalan!#LULreunion##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_kr = "#C0x5B545B#오랜만이에요! 저는 #C0x5C9971#{name}.#C0x5B545B# 초대를 수락하고 작업을 완료할 수 있도록 도와주세요! 풍성한 보상을 받으실 수 있습니다!#LULreunion##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_th = "#C0x5B545B#ไม่เจอกันนาน! ฉัน #C0x5C9971#{name}.#C0x5B545B# ยอมรับคำเชิญของฉันและช่วยฉันทำงานให้เสร็จ! คุณจะได้รับรางวัลมากมาย!#LULreunion##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_es = "#C0x5B545B#¡Cuánto tiempo sin verte! Soy #C0x5C9971#{name}.#C0x5B545B# ¡Acepta mi invitación y ayúdame a completar las tareas! ¡Obtendrás ricas recompensas! #LULreunion##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text = "#C0x5B545B#Long time no see! I'm #C0x5C9971#{name}.#C0x5B545B# Accept my invitation and help me complete the tasks! You will get rich rewards!#LULreunion##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		id = 1099
	},
