	[6319] = {
		text_en = "#C0x55504D#(Initiating and winning the challenge gives #C0xEF3453#+2#C0x55504D# points, while losing gives #C0xEF3453#+1#C0x55504D# points. Trainers who have attained VIP5 or level 45 and above can also earn #C0xEF3453#+2#C0x55504D# points)",
		key = "rankPointRule",
		text_vn = "#C0x55504D#(Iniciar e vencer o desafio dá #C0xEF3453#+2#C0x55504D# pontos, enquanto perder dá #C0xEF3453#+1#C0x55504D# pontos. Treinadores que atingiram VIP5 ou nível 45 e superior também podem ganhar #C0xEF3453#+ 2#C0x55504D# pontos)",
		text_id = "#C0x55504D#(inisiasi dan memenangkan tantangan akan memberikan #C0xEF3453#+2#C0x55504D# poin, sedangkan kalah akan mendapatkan #C0xEF3453#+1#C0x55504D# poin. Trainer yang telah mencapai VIP5 atau level 45 ke atas juga bisa mendapatkan #C0xEF3453#+ 2#C0x55504D# poin)",
		text_kr = "#C0x55504D#(챌린지를 시작하고 승리하면 #C0xEF3453#+2#C0x55504D# 포인트를 얻고, 패배하면 #C0xEF3453#+1#C0x55504D# 포인트를 얻습니다. VIP5 또는 레벨 45 이상을 달성한 트레이너도 #C0xEF3453#+를 얻을 수 있습니다. 2#C0x55504D# 포인트)",
		text_th = "#C0x55504D#(การเริ่มต้นและชนะการท้าทายจะให้ #C0xEF3453#+2#C0x55504D# คะแนน ในขณะที่แพ้จะให้ #C0xEF3453#+1#C0x55504D# คะแนน เทรนเนอร์ที่ได้รับ VIP5 หรือระดับ 45 ขึ้นไปก็สามารถรับ #C0xEF3453#+ ได้เช่นกัน 2#C0x55504D# คะแนน)",
		text_es = "#C0x55504D#(Iniciar y ganar el desafío otorga #C0xEF3453#+2#C0x55504D# puntos, mientras que perder otorga #C0xEF3453#+1#C0x55504D# puntos. Los entrenadores que hayan alcanzado VIP5 o nivel 45 y superior también pueden ganar #C0xEF3453#+ 2#C0x55504D# puntos)",
		text = "#C0x55504D#(Initiating and winning the challenge gives #C0xEF3453#+2#C0x55504D# points, while losing gives #C0xEF3453#+1#C0x55504D# points. Trainers who have attained VIP5 or level 45 and above can also earn #C0xEF3453#+2#C0x55504D# points)",
		id = 6319
	},
