	[6721] = {
		text_en = "#C0x5b545b# Held Item have been equipped on the Pokémon %s#C0x5b545b#, do you continue to rebirth?",
		key = "heldItemIsDress",
		text_vn = "#C0x5b545b# Held Item foi equipado no Pokémon %s#C0x5b545b#, você continua renascendo?",
		text_id = "#C0x5b545b# Item yang Dimiliki telah dipasang di Pokémon %s#C0x5b545b#, apakah Anda terus terlahir kembali?",
		text_kr = "#C0x5b545b# 소지아이템이 포켓몬 %s에 장착되었습니다#C0x5b545b#, 계속 환생하시나요?",
		text_th = "#C0x5b545b# ไอเทมที่ถูกสวมใส่บนโปเกมอน %s#C0x5b545b# คุณจะเกิดใหม่ต่อไปหรือไม่?",
		text_es = "#C0x5b545b# Los objetos retenidos han sido equipados en el Pokémon %s#C0x5b545b#, ¿continúas renaciendo?",
		text = "#C0x5b545b# Held Item have been equipped on the Pokémon %s#C0x5b545b#, do you continue to rebirth?",
		id = 6721
	},
	[6722] = {
		text_en = "#C0x5b545b#%s#C0x5b545b# will soon reborn. Besides #C0x60C456#Nature, Individual Value, Effort Value and Friendship#C0x5b545b#, other stats will#C0xF76B45# return to its initial state#C0x5b545b#. Do you want to continue?",
		key = "rebirthCardTip",
		text_vn = "#C0x5b545b#%s#C0x5b545b# logo renascerá. Além de #C0x60C456#Natureza, Valor Individual, Valor do Esforço e Amizade#C0x5b545b#, outras estatísticas irão#C0xF76B45# retornar ao seu estado inicial#C0x5b545b#. Você quer continuar?",
		text_id = "#C0x5b545b#%s#C0x5b545b# akan segera terlahir kembali. Selain #C0x60C456#Sifat, Nilai Individu, Nilai Usaha, dan pertemanan#C0x5b545b#, statistik lainnya akan#C0xF76B45# kembali ke keadaan awal#C0x5b545b#. Apakah Anda ingin melanjutkan?",
		text_kr = "#C0x5b545b#%s#C0x5b545b# 곧 다시 태어납니다. #C0x60C456#자연, 개인의 가치, 노력의 가치, 우정#C0x5b545b# 외에도 다른 통계#C0xF76B45#가 초기 상태#C0x5b545b#로 돌아갑니다. 계속하시겠습니까?",
		text_th = "#C0x5b545b#%s#C0x5b545b# จะเกิดใหม่ในไม่ช้า นอกจาก #C0x60C456#ธรรมชาติ คุณค่าส่วนบุคคล คุณค่าความพยายาม และมิตรภาพ#C0x5b545b# แล้วสถิติอื่นๆ จะ#C0xF76B45# กลับไปสู่สถานะเริ่มต้น#C0x5b545b# คุณต้องการดำเนินการต่อหรือไม่?",
		text_es = "#C0x5b545b#%s#C0x5b545b# pronto renacerá. Además de #C0x60C456#Naturaleza, Valor Individual, Valor del Esfuerzo y Amistad#C0x5b545b#, otras estadísticas#C0xF76B45# volverán a su estado inicial#C0x5b545b#. ¿Quieres continuar?",
		text = "#C0x5b545b#%s#C0x5b545b# will soon reborn. Besides #C0x60C456#Nature, Individual Value, Effort Value and Friendship#C0x5b545b#, other stats will#C0xF76B45# return to its initial state#C0x5b545b#. Do you want to continue?",
		id = 6722
	},
	[6723] = {
		text_en = "#C0x5b545b# The selected Pokémon is about to be reborn and decomposed, the training resources used in its #C0x60C456# individual value, effort value #C0x5b545b# will all be #C0xF76B45# gone #C0x5b545b#. Continue?",
		key = "decomposeCardTip",
		text_vn = "#C0x5b545b# O Pokémon selecionado está prestes a renascer e se decompor, os recursos de treinamento utilizados em seu #C0x60C456# valor individual, valor de esforço #C0x5b545b# todos terão #C0xF76B45# desaparecido #C0x5b545b#. Continuar?",
		text_id = "#C0x5b545b# Pokémon yang dipilih akan dilahirkan kembali dan menguraikan, sumber daya Traineran yang digunakan dalam #C0x60C456# nilai individu, nilai usaha #C0x5b545b# semuanya akan #C0xF76B45# hilang #C0x5b545b#. Melanjutkan?",
		text_kr = "#C0x5b545b# 선택된 포켓몬은 다시 태어나고 분해될 예정이며, #C0x60C456# 개인의 가치, 노력의 가치 #C0x5b545b# 에 사용된 훈련 자원은 모두 #C0xF76B45# 사라지게 됩니다 #C0x5b545b#. 계속하다?",
		text_th = "#C0x5b545b# โปเกมอนที่เลือกกำลังจะเกิดใหม่และสลายไป ทรัพยากรการฝึกที่ใช้ใน #C0x60C456# คุณค่าส่วนบุคคล คุณค่าความพยายาม #C0x5b545b# จะทั้งหมด #C0xF76B45# หายไป #C0x5b545b# ดำเนินการต่อ?",
		text_es = "#C0x5b545b# El Pokémon seleccionado está a punto de renacer y descomponerse, los recursos de entrenamiento utilizados en su #C0x60C456# valor individual, valor de esfuerzo #C0x5b545b# todos desaparecerán #C0xF76B45# #C0x5b545b#. ¿Continuar?",
		text = "#C0x5b545b# The selected Pokémon is about to be reborn and decomposed, the training resources used in its #C0x60C456# individual value, effort value #C0x5b545b# will all be #C0xF76B45# gone #C0x5b545b#. Continue?",
		id = 6723
	},
	[6724] = {
		text_en = "#C0x5b545b#About to reset Held Item that being selected, level will be reset to #C0xF76B45#default#C0x5b545b#, do you confirm?",
		key = "rebirthHeldItemTip",
		text_vn = "#C0x5b545b#Prestes a redefinir o item retido que está sendo selecionado, o nível será redefinido para #C0xF76B45#padrão#C0x5b545b#, você confirma?",
		text_id = "#C0x5b545b#Akan reset Item yang Ditahan yang dipilih, level akan diatur ulang ke #C0xF76B45#default#C0x5b545b#, apakah Anda mengonfirmasi?",
		text_kr = "#C0x5b545b#선택한 보유 아이템을 재설정하려고 하면 레벨이 #C0xF76B45#기본#C0x5b545b#으로 재설정됩니다. 확인하시겠습니까?",
		text_th = "#C0x5b545b#กำลังจะรีเซ็ตรายการที่ถูกเลือก ระดับจะถูกรีเซ็ตเป็น #C0xF76B45#ค่าเริ่มต้น#C0x5b545b# คุณยืนยันหรือไม่?",
