		text_id = "Jaminan undian 10x Green Orb dan Universal Shard",
		text_kr = "10배 뽑기 보장 그린 오브 및 유니버설 샤드",
		text_th = "รับประกันการเสมอ 10 เท่า Green Orb และ Universal Shard",
		text_es = "10x sorteo garantizado Green Orb y Universal Shard",
