	},
	[7015] = {
		text_en = "#C0x5B545B#The training level of the selection item is more than 1, #C0xF76B45# no materials will be returned if it is used for breakthough#C0x5B545B#. Do you want to continue?#C0x60C456#(Training materials can be returned through rebirth)",
		key = "heldItemAdvanceLvTip",
		text_vn = "#C0x5B545B#O nível de treinamento do item de seleção é superior a 1, #C0xF76B45# nenhum material será devolvido se for usado para avanço#C0x5B545B#. Quer continuar?#C0x60C456#(Os materiais de treinamento podem ser devolvidos através do renascimento)",
		text_id = "#C0x5B545B#Level latihan item yang dipilih lebih dari 1, #C0xF76B45# materi tidak akan dikembalikan jika digunakan untuk breakthrough#C0x5B545B#. Apakah Anda ingin melanjutkan?#C0x60C456#(Materi Traineran dapat dikembalikan melalui kelahiran kembali)",
		text_kr = "#C0x5B545B#선택항목의 훈련레벨이 1이상입니다. #C0xF76B45# 돌파용으로 사용시 재료는 반환되지 않습니다#C0x5B545B#. 계속하시겠습니까?#C0x60C456#(교육자료는 환생을 통해 반환될 수 있습니다)",
		text_th = "#C0x5B545B#ระดับการฝึกของรายการคัดเลือกมากกว่า 1 #C0xF76B45# จะไม่มีการคืนวัสดุหากใช้เพื่อหยุดพัก#C0x5B545B# คุณต้องการดำเนินการต่อหรือไม่?#C0x60C456#(อุปกรณ์การฝึกอบรมสามารถคืนได้เมื่อเกิดใหม่)",
		text_es = "#C0x5B545B#El nivel de entrenamiento del elemento de selección es superior a 1, #C0xF76B45# no se devolverán materiales si se utilizan para avances#C0x5B545B#. ¿Quieres continuar? #C0x60C456# (Los materiales de capacitación se pueden devolver mediante el renacimiento)",
		text = "#C0x5B545B#The training level of the selection item is more than 1, #C0xF76B45# no materials will be returned if it is used for breakthough#C0x5B545B#. Do you want to continue?#C0x60C456#(Training materials can be returned through rebirth)",
		id = 7015
	},
	[7016] = {
		text_en = "#C0x5B545B#The selected item is currently worn by %s#C0x5B545B#. Are you sure you want to use it? (#C0x60C456#The item will be removed if you proceed#C0x5B545B#)",
		key = "heldItemAdvanceDressTip",
		text_vn = "#C0x5B545B#O item selecionado é usado atualmente por %s#C0x5B545B#. Tem certeza de que deseja usá-lo? (#C0x60C456#O item será removido se você prosseguir#C0x5B545B#)",
		text_id = "#C0x5B545B#Item yang dipilih saat ini dipakai oleh %s#C0x5B545B#. Apakah Anda yakin ingin menggunakannya? (#C0x60C456#Item akan dihapus jika Anda melanjutkan#C0x5B545B#)",
		text_kr = "#C0x5B545B#선택한 아이템은 현재 %s님이 착용하고 있습니다#C0x5B545B#. 정말로 사용하시겠습니까? (#C0x60C456#계속 진행하시면 해당 항목이 삭제됩니다#C0x5B545B#)",
		text_th = "#C0x5B545B#รายการที่เลือกขณะนี้สวมใส่โดย %s#C0x5B545B# คุณแน่ใจหรือไม่ว่าต้องการใช้มัน? (#C0x60C456#รายการจะถูกลบออกหากคุณดำเนินการต่อ#C0x5B545B#)",
		text_es = "#C0x5B545B#El artículo seleccionado lo usa actualmente %s#C0x5B545B#. ¿Estás seguro de que quieres usarlo? (#C0x60C456#El artículo se eliminará si continúas#C0x5B545B#)",
		text = "#C0x5B545B#The selected item is currently worn by %s#C0x5B545B#. Are you sure you want to use it? (#C0x60C456#The item will be removed if you proceed#C0x5B545B#)",
