	[7042] = {
		text_en = "#C0xF7A57C##F30##L10#For every#C0xFFF8E0##F40##L10#%d#Icommon/icon/icon_diamond.png-41-37##C0xF7A57C##F30##L10#spent, you get#C0xFFFF7F##F40##L10#%d#C0xF7A57C##F30##L10#points. The points are only valid for the current event.",
