		text_th = "#C0x5b545b#คุณต้องการจ่าย %s#Icommon/icon/icon_diamond.png-56-56##C0x5b545b# เพื่อรีเซ็ตระดับหรือไม่?",
		text_es = "#C0x5b545b#¿Quieres gastar %s#Icommon/icon/icon_diamond.png-56-56##C0x5b545b# para restablecer el nivel?",
		text = "#C0x5b545b#Do you want to spend %s#Icommon/icon/icon_diamond.png-56-56##C0x5b545b# to reset the level?",
		id = 7076
	},
	[7077] = {
		text_en = "#C0x5b545b#This Pokémon's type will switch from #I%s-60-60##C0x5b545b# to #I%s-60-60##C0x5b545b# as the team aura has taken effect. After switching it will be effective in all formation interface. Do you want to continue?",
		key = "chooseNatureText",
		text_vn = "#C0x5b545b#O tipo deste Pokémon mudará de #I%s-60-60##C0x5b545b# para #I%s-60-60##C0x5b545b# conforme a aura da equipe entrar em vigor. Após a troca, ele terá efeito em todas as interfaces de formação. Você quer continuar?",
		text_id = "#C0x5b545b#Tipe Pokémon ini akan berubah dari #I%s-60-60##C0x5b545b# menjadi #I%s-60-60##C0x5b545b# saat aura tim mulai berlaku. Setelah peralihan, ini akan efektif di semua antar andaka formasi. Apakah Anda ingin melanjutkan?",
		text_kr = "#C0x5b545b#팀 오라가 적용됨에 따라 이 포켓몬의 유형이 #I%s-60-60##C0x5b545b#에서 #I%s-60-60##C0x5b545b#로 변경됩니다. 전환 후에는 모든 포메이션 인터페이스에 적용됩니다. 계속하시겠습니까?",
		text_th = "#C0x5b545b# ประเภทของโปเกมอนนี้จะเปลี่ยนจาก #I%s-60-60##C0x5b545b# เป็น #I%s-60-60##C0x5b545b# เมื่อออร่าของทีมมีผล หลังจากเปลี่ยนแล้วจะมีผลกับอินเทอร์เฟซรูปแบบทั้งหมด คุณต้องการดำเนินการต่อหรือไม่?",
		text_es = "#C0x5b545b#El tipo de este Pokémon cambiará de #I%s-60-60##C0x5b545b# a #I%s-60-60##C0x5b545b# cuando el aura del equipo haya entrado en vigor. Después del cambio, será efectivo en todas las interfaces de formación. ¿Quieres continuar?",
		text = "#C0x5b545b#This Pokémon's type will switch from #I%s-60-60##C0x5b545b# to #I%s-60-60##C0x5b545b# as the team aura has taken effect. After switching it will be effective in all formation interface. Do you want to continue?",
		id = 7077
	},
