	[7457] = {
		text_en = "During the fishing contest, the fish caught in this scene are not counted as points in the competition. Are the consumption times and automatic fishing of bait determined?",
		key = "fishGameStartIsAutoFishing",
		text_vn = "Durante a competição de pesca, os peixes capturados nesta cena não contam como pontos na competição. Os tempos de consumo e pesca automática das iscas são determinados?",
		text_id = "Selama kontes memancing, ikan yang ditangkap dalam adegan ini tidak dihitung sebagai poin dalam kompetisi. Apakah waktu konsumsi dan penangkapan umpan otomatis ditentukan?",
		text_kr = "낚시 대회 중 이 장면에서 잡힌 물고기는 대회 점수로 계산되지 않습니다. 미끼 소모시간과 자동낚시 시간이 정해져 있나요?",
		text_th = "ในระหว่างการแข่งขันตกปลา ปลาที่จับได้ในฉากนี้จะไม่นับเป็นคะแนนในการแข่งขัน กำหนดเวลาการบริโภคและการตกปลาเหยื่ออัตโนมัติหรือไม่?",
		text_es = "Durante el concurso de pesca, los peces capturados en esta escena no cuentan como puntos en el concurso. ¿Se determinan los tiempos de consumo y pesca automática del cebo?",
		text = "During the fishing contest, the fish caught in this scene are not counted as points in the competition. Are the consumption times and automatic fishing of bait determined?",
		id = 7457
	},
	[7458] = {
		text_en = "During the fishing contest, the fish caught in this scene are not counted in the competition points. Are you sure you want to fish?",
		key = "fishGameStartIsFishing",
		text_vn = "Durante a competição de pesca, os peixes capturados nesta cena não contam nos pontos da competição. Tem certeza que quer pescar?",
		text_id = "Selama kontes memancing, ikan yang ditangkap dalam adegan ini tidak dihitung dalam poin kompetisi. Apakah Anda yakin ingin memancing?",
		text_kr = "낚시 대회 중 이 장면에서 잡힌 물고기는 대회 포인트에 포함되지 않습니다. 정말 낚시하고 싶으신가요?",
