	[7460] = {
		text_en = "#C0x5B545B# has been placed #C0xF76B45##L10#3#C0xFF5B545B##L0# runestones, after consumption #C0xF76B45##L10# can be replaced with 2 new runestones #C0xFF5B545B##L0# (if runestones have been Reinforcement, the reinforcement materials will be returned free of charge), do you confirm the replacement?",
		key = "gemUpNum",
		text_vn = "#C0x5B545B# foi colocado #C0xF76B45##L10#3#C0xFF5B545B##L0# pedras rúnicas, após o consumo #C0xF76B45##L10# podem ser substituídas por 2 novas pedras rúnicas #C0xFF5B545B##L0# (se as pedras rúnicas foram de Reforço, o os materiais de reforço serão devolvidos gratuitamente), você confirma a substituição?",
		text_id = "#C0x5B545B# telah ditempatkan #C0xF76B45##L10#3#C0xFF5B545B##L0# runestone, setelah dikonsumsi #C0xF76B45##L10# dapat diganti dengan 2 runestone baru #C0xFF5B545B##L0# (jika runestone sudah menjadi Reinforcement, maka bahan penguat akan dikembalikan secara gratis), apakah Anda mengkonfirmasi penggantiannya?",
		text_kr = "#C0x5B545B# 배치되었습니다 #C0xF76B45##L10#3#C0xFF5B545B##L0# 룬스톤, 소비 후 #C0xF76B45##L10# 2개의 새로운 룬스톤으로 교체 가능 #C0xFF5B545B##L0# (룬스톤이 강화인 경우, 보강재는 무료로 반품해 드립니다), 교체를 확인하셨나요?",
		text_th = "#C0x5B545B# ถูกวาง #C0xF76B45##L10#3#C0xFF5B545B##L0# หินรูน หลังจากการบริโภค #C0xF76B45##L10# สามารถถูกแทนที่ด้วยหินรูนใหม่ 2 ก้อน #C0xFF5B545B##L0# (หากหินรูนได้รับการเสริมแรงแล้ว วัสดุเสริมจะถูกส่งคืนฟรี) คุณยืนยันการเปลี่ยนหรือไม่?",
		text_es = "#C0x5B545B# se ha colocado #C0xF76B45##L10#3#C0xFF5B545B##L0# piedras rúnicas, después del consumo #C0xF76B45##L10# se puede reemplazar con 2 nuevas piedras rúnicas #C0xFF5B545B##L0# (si las piedras rúnicas han sido Refuerzo, las los materiales de refuerzo se devolverán sin cargo), ¿confirman el reemplazo?",
