	[7498] = {
		text_en = "#C0x5b545b#Development materials have been invested in this Pokémon. #C0xF76B45#No materials will be returned after the consumption. #C0x5b545b#Continue? #C0x60C456#(Development materials will be returned through Rebirth.)",
		key = "selectCardMaterialsMega",
		text_vn = "#C0x5b545b#Materiais de desenvolvimento foram investidos neste Pokémon. #C0xF76B45#Nenhum material será devolvido após o consumo. #C0x5b545b#Continuar? #C0x60C456#(Os materiais de desenvolvimento serão devolvidos através do Rebirth.)",
		text_id = "#C0x5b545b#Material pengembangan telah diinvestasikan pada Pokémon ini. #C0xF76B45#Tidak ada bahan yang akan dikembalikan setelah dikonsumsi. #C0x5b545b#Lanjutkan? #C0x60C456#(Materi pengembangan akan dikembalikan melalui Kelahiran Kembali.)",
		text_kr = "#C0x5b545b#이 포켓몬에는 개발 재료가 투자되었습니다. #C0xF76B45#사용 후 재료는 반환되지 않습니다. #C0x5b545b#계속할까요? #C0x60C456#(개발자재는 Rebirth를 통해 반환됩니다.)",
		text_th = "#C0x5b545b#ลงทุนวัสดุการพัฒนากับโปเกมอนตัวนี้แล้ว #C0xF76B45#จะไม่มีการคืนวัสดุใด ๆ หลังจากการบริโภค #C0x5b545b#ไปต่อ? #C0x60C456#(วัสดุการพัฒนาจะถูกส่งกลับผ่านการเกิดใหม่)",
		text_es = "#C0x5b545b#Se han invertido materiales de desarrollo en este Pokémon. #C0xF76B45#No se devolverán materiales después del consumo. #C0x5b545b#¿Continuar? #C0x60C456#(Los materiales de desarrollo se devolverán a través de Rebirth).",
		text = "#C0x5b545b#Development materials have been invested in this Pokémon. #C0xF76B45#No materials will be returned after the consumption. #C0x5b545b#Continue? #C0x60C456#(Development materials will be returned through Rebirth.)",
