	[7696] = {
		text_en = "#LOC0x5A545B##F38##C0xFEFDEC#Challenge #C0xAEE97E#any#C0xFEFDEC# difficulty, get Badge material \nAfter clear all difficulties, challenge to become#C0xECB72A# server Honor Gym Leader!",
		key = "gymGateDesc",
		text_vn = "#LOC0x5A545B##F38##C0xFEFDEC#Desafie #C0xAEE97E#qualquer#C0xFEFDEC# dificuldade, obtenha material de emblema \nDepois de superar todas as dificuldades, desafie para se tornar#C0xECB72A# servidor Honor Gym Leader!",
		text_id = "#LOC0x5A545B##F38##C0xFEFDEC#Tantangan #C0xAEE97E#setiap#C0xFEFDEC# Level kesulitan, dapatkan materi Lencana \nSetelah menyelesaikan semua kesulitan, tantang untuk menjadi#C0xECB72A# server Honor Gym Leader!",
		text_kr = "#LOC0x5A545B##F38##C0xFEFDEC#도전 #C0xAEE97E#any#C0xFEFDEC# 난이도, 뱃지 재료 획득 \n모든 난이도 클리어 후 도전#C0xECB72A# 서버 명예 체육관 관장!",
		text_th = "#LOC0x5A545B##F38##C0xFEFDEC#ท้าทาย #C0xAEE97E#ความยากใดก็ได้#C0xFEFDEC# รับวัสดุตราสัญลักษณ์ \nหลังจากเคลียร์ความยากลำบากทั้งหมดแล้ว ท้าทายที่จะกลายเป็น#C0xECB72A# เซิร์ฟเวอร์ ให้เกียรติหัวหน้ายิม!",
		text_es = "#LOC0x5A545B##F38##C0xFEFDEC#Desafía #C0xAEE97E#cualquier#C0xFEFDEC# dificultad, obtén material de insignia. \nDespués de superar todas las dificultades, desafía a convertirte en#C0xECB72A# ¡Líder del gimnasio de honor del servidor!",
		text = "#LOC0x5A545B##F38##C0xFEFDEC#Challenge #C0xAEE97E#any#C0xFEFDEC# difficulty, get Badge material \nAfter clear all difficulties, challenge to become#C0xECB72A# server Honor Gym Leader!",
