	[7756] = {
		text_en = "#C0xFFFFFF##Pfont/youmi1.ttf#You've been offline for #C0x99FF99##Pfont/youmi1.ttf#%d day(s)#C0xFFFFFF##Pfont/youmi1.ttf#. Sign in now and get the following rewards!",
		key = "reunionSignText",
		text_vn = "#C0xFFFFFF##Pfont/youmi1.ttf#Você está off-line há #C0x99FF99##Pfont/youmi1.ttf#%d dia(s)#C0xFFFFFF##Pfont/youmi1.ttf#. Faça login agora e receba as seguintes recompensas!",
		text_id = "#C0xFFFFFF##Pfont/youmi1.ttf#Anda telah offline selama #C0x99FF99##Pfont/youmi1.ttf#%d hari#C0xFFFFFF##Pfont/youmi1.ttf#. Masuk sekarang dan dapatkan hadiah berikut!",
		text_kr = "#C0xFFFFFF##Pfont/youmi1.ttf#당신은 #C0x99FF99##Pfont/youmi1.ttf#%d일#C0xFFFFFF##Pfont/youmi1.ttf# 동안 오프라인 상태였습니다. 지금 로그인하고 다음 보상을 받으세요!",
		text_th = "#C0xFFFFFF##Pfont/youmi1.ttf#คุณออฟไลน์มา #C0x99FF99##Pfont/youmi1.ttf#%d วัน#C0xFFFFFF##Pfont/youmi1.ttf# ลงชื่อเข้าใช้ตอนนี้และรับรางวัลดังต่อไปนี้!",
		text_es = "#C0xFFFFFF##Pfont/youmi1.ttf#Has estado desconectado durante #C0x99FF99##Pfont/youmi1.ttf#%d día(s)#C0xFFFFFF##Pfont/youmi1.ttf#. ¡Inicia sesión ahora y obtén las siguientes recompensas!",
		text = "#C0xFFFFFF##Pfont/youmi1.ttf#You've been offline for #C0x99FF99##Pfont/youmi1.ttf#%d day(s)#C0xFFFFFF##Pfont/youmi1.ttf#. Sign in now and get the following rewards!",
		id = 7756
