	[7763] = {
		text_en = "#L00000010##C0x5B545B#Congratulations! You've bound with #L00000010##C0xF13B54# [%s] #L00000010##C0x5B545B#!",
		key = "reunionTaskOldText",
		text_vn = "#L00000010##C0x5B545B#Parabéns! Você ligou com #L00000010##C0xF13B54# [%s] #L00000010##C0x5B545B#!",
		text_id = "#L00000010##C0x5B545B#Selamat! Anda telah terikat dengan #L00000010##C0xF13B54# [%s] #L00000010##C0x5B545B#!",
		text_kr = "#L00000010##C0x5B545B#축하해요! #L00000010##C0xF13B54# [%s] #L00000010##C0x5B545B#과 함께하셨습니다!",
		text_th = "#L00000010##C0x5B545B#ยินดีด้วย! คุณผูกพันกับ #L00000010##C0xF13B54# [%s] #L00000010##C0x5B545B#!",
		text_es = "#L00000010##C0x5B545B#¡Felicidades! ¡Has atado con #L00000010##C0xF13B54# [%s] #L00000010##C0x5B545B#!",
		text = "#L00000010##C0x5B545B#Congratulations! You've bound with #L00000010##C0xF13B54# [%s] #L00000010##C0x5B545B#!",
		id = 7763
	},
	[7764] = {
		text_en = "#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#*Only your joined quests will be shown here. Get your friends to complete their quests and you will all get more chest rewards!",
		key = "reunionTaskBindToText",
		text_vn = "#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#*Apenas suas missões unidas serão mostradas aqui. Faça com que seus amigos completem suas missões e todos vocês receberão mais recompensas no baú!",
		text_id = "#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#*Hanya misi gabungan Anda yang akan ditampilkan di sini. Ajak teman anda untuk menyelesaikan misi mereka dan kalian semua akan mendapatkan lebih banyak hadiah peti!",
		text_kr = "#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#*여기에는 귀하가 참여한 퀘스트만 표시됩니다. 친구들이 퀘스트를 완료하도록 유도하면 모두 더 많은 상자 보상을 받을 수 있습니다!",
		text_th = "#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#*เฉพาะภารกิจที่คุณเข้าร่วมเท่านั้นที่จะแสดงที่นี่ พาเพื่อนของคุณมาทำภารกิจให้สำเร็จแล้วคุณทุกคนจะได้รับรางวัลหีบมากขึ้น!",
		text_es = "#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#*Aquí solo se mostrarán tus misiones unidas. ¡Haz que tus amigos completen sus misiones y todos obtendrán más recompensas en cofres!",
		text = "#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#*Only your joined quests will be shown here. Get your friends to complete their quests and you will all get more chest rewards!",
		id = 7764
	},
	[7765] = {
		text_en = "#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#*Bind one Pro Trainer to unlock Reunion Quest. Complete the quests to get rewards! What's more, you and the Pro Trainer will both get Point rewards!",
		key = "reunionBindTextByReunion",
		text_vn = "#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#*Vincule um Pro Trainer para desbloquear a Reunion Quest. Complete as missões para obter recompensas! Além do mais, você e o Pro Trainer receberão recompensas em pontos!\"\"\"",
		text_id = "#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#*Ikat satu Trainer Pro untuk membuka Reunion Quest. Selesaikan misi untuk mendapatkan hadiah! Terlebih lagi, Anda dan Trainer Pro akan mendapatkan hadiah Poin!\"\"\"",
		text_kr = "#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#*프로 트레이너 한 명을 결속해 재회 퀘스트를 잠금 해제하세요. 퀘스트를 완료하고 보상을 받으세요! 게다가 귀하와 프로 트레이너 모두 포인트 보상을 받게 됩니다!\"\"\"",
		text_th = "#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#*ผูก Pro Trainer หนึ่งตัวเพื่อปลดล็อก Reunion Quest ทำภารกิจให้สำเร็จเพื่อรับรางวัล! ยิ่งไปกว่านั้น คุณและ Pro Trainer จะได้รับรางวัลคะแนนทั้งคู่!\"\"\"",
		text_es = "#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#* Vincula un entrenador profesional para desbloquear Reunion Quest. ¡Completa las misiones para obtener recompensas! ¡Además, tanto tú como el entrenador profesional obtendréis puntos de recompensa!\"",
		text = "#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#*Bind one Pro Trainer to unlock Reunion Quest. Complete the quests to get rewards! What's more, you and the Pro Trainer will both get Point rewards!",
		id = 7765
	},
	[7766] = {
		text_en = "#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#*Congratulations! You've bound with [#L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#]! Help the returned players complete the quests and get Reunion Packs!",
		key = "reunionBindTextBySenior",
		text_vn = "#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#*Parabéns! Você ligou com [#L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#]! Ajude os jogadores que retornaram a completar as missões e ganhe Pacotes de Reunião!",
		text_id = "#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#*Selamat! Anda telah terikat dengan [#L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#]! Bantu pemain yang kembali menyelesaikan misi dan mendapatkan Paket Reuni!",
		text_kr = "#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#*축하합니다! [#L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#]와 함께 하셨습니다! 돌아온 플레이어가 퀘스트를 완료하고 리유니온 팩을 얻을 수 있도록 도와주세요!",
		text_th = "#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#*ยินดีด้วย! ผูกพันกับ [#L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#]! ช่วยผู้เล่นที่กลับมาทำภารกิจให้สำเร็จและรับ Reunion Packs!",
		text_es = "#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#*¡Felicidades! ¡Has atado con [#L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#]! ¡Ayuda a los jugadores que regresaron a completar las misiones y obtener paquetes de reunión!",
		text = "#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#*Congratulations! You've bound with [#L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#]! Help the returned players complete the quests and get Reunion Packs!",
		id = 7766
	},
