	[7910] = {
		text_en = "The first switch costs #C0xF76B45#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B#(#C0x5C9970#No more cost for more switches of the same Pokémon. #C0xF76B45#But switches of new Pokémon of the same series still cost Diamonds#C0x5B545B#). Continue? (All the development will be inherited after the switching.)",
		key = "onSwitchChangeShape",
		text_vn = "A primeira troca custa #C0xF76B45#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B#(#C0x5C9970#Não há mais custo para mais trocas do mesmo Pokémon. #C0xF76B45#Mas trocas de novos Pokémon da mesma série ainda custam Diamantes#C0x5B545B#). Continuar? (Todo o desenvolvimento será herdado após a troca.)",
		text_id = "Peralihan pertama dikenakan biaya #C0xF76B45#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B#(#C0x5C9970#Tidak ada biaya tambahan untuk penukaran lebih banyak Pokémon yang sama. #C0xF76B45#Tetapi penukaran Pokémon baru dari seri yang sama tetap memerlukan diamond#C0x5B545B#). Melanjutkan? (semua pengembangan akan diwarisi setelah peralihan.)",
		text_kr = "첫 번째 스위치 비용은 #C0xF76B45#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B#(#C0x5C9970#같은 포켓몬을 더 이상 스위치하는 데 더 이상 비용이 들지 않습니다. #C0xF76B45#하지만 같은 시리즈의 새 포켓몬 스위치는 여전히 다이아몬드#C0x5B545B#)입니다. 계속하다? (전환 후 모든 개발은 상속됩니다.)",
		text_th = "สวิตช์ตัวแรกมีราคา #C0xF76B45#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B#(#C0x5C9970#ไม่มีค่าใช้จ่ายเพิ่มเติมสำหรับสวิตช์ของโปเกมอนตัวเดียวกันเพิ่มเติม #C0xF76B45#แต่สวิตช์ของโปเกมอนตัวใหม่ในซีรีส์เดียวกันยังคงมีราคาเพชร#C0x5B545B#) ดำเนินการต่อ? (การพัฒนาทั้งหมดจะสืบทอดหลังจากการสลับ)",
		text_es = "El primer cambio cuesta #C0xF76B45#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B#(#C0x5C9970#No hay más costo por más cambios del mismo Pokémon. #C0xF76B45#Pero los cambios de nuevos Pokémon de la misma serie todavía cuestan Diamantes#C0x5B545B#). ¿Continuar? (Todo el desarrollo se heredará después del cambio).",
		text = "The first switch costs #C0xF76B45#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B#(#C0x5C9970#No more cost for more switches of the same Pokémon. #C0xF76B45#But switches of new Pokémon of the same series still cost Diamonds#C0x5B545B#). Continue? (All the development will be inherited after the switching.)",
		id = 7910
	},
