	[7933] = {
		text_en = "#C0x5B545B#All #C0x3C8B99#Gym Dungeon#C0x5B545B#, #C0x3C8B99#Honorary Gym Leader#C0x5B545B# and #C0x3C8B99#Challenge Buff#C0x5B545B# are about to reset. New challenges are waiting!",
		key = "gymReset",
		text_vn = "#C0x5B545B#Todos os #C0x3C8B99#Gym Dungeon#C0x5B545B#, #C0x3C8B99#Honorary Gym Leader#C0x5B545B# e #C0x3C8B99#Challenge Buff#C0x5B545B# estão prestes a reiniciar. Novos desafios estão esperando!",
		text_id = "#C0x5B545B#semua #C0x3C8B99#Gym Dungeon#C0x5B545B#, #C0x3C8B99#Honorary Gym Leader#C0x5B545B# dan #C0x3C8B99#Challenge Buff#C0x5B545B# akan direset. Tantangan baru sedang menunggu!",
		text_kr = "#C0x5B545B#모두 #C0x3C8B99#체육관 던전#C0x5B545B#, #C0x3C8B99#명예 체육관 관장#C0x5B545B#, #C0x3C8B99#도전 버프#C0x5B545B#가 초기화됩니다. 새로운 도전이 기다리고 있습니다!",
		text_th = "#C0x5B545B#ทั้งหมด #C0x3C8B99#ยิมดันเจี้ยน#C0x5B545B#, #C0x3C8B99#ผู้นำยิมกิตติมศักดิ์#C0x5B545B# และ #C0x3C8B99#Challenge Buff#C0x5B545B# กำลังจะรีเซ็ต ความท้าทายใหม่กำลังรออยู่!",
		text_es = "#C0x5B545B#Todos los #C0x3C8B99#Gym Dungeon#C0x5B545B#, #C0x3C8B99#Líder de gimnasio honorario#C0x5B545B# y #C0x3C8B99#Challenge Buff#C0x5B545B# están a punto de reiniciarse. ¡Te esperan nuevos desafíos!",
		text = "#C0x5B545B#All #C0x3C8B99#Gym Dungeon#C0x5B545B#, #C0x3C8B99#Honorary Gym Leader#C0x5B545B# and #C0x3C8B99#Challenge Buff#C0x5B545B# are about to reset. New challenges are waiting!",
		id = 7933
	},
