	[7936] = {
		text_en = "#C0x5B545B#You've #C0x5C9970#occupied #C0x5B545B#server %s. Congratulations!#C0x5C9970# You are now qualified to compete for the position of Honorary Gym Leader!",
		key = "gymOccupy",
		text_vn = "#C0x5B545B#Você #C0x5C9970#ocupou #C0x5B545B#servidor %s. Parabéns!#C0x5C9970# Agora você está qualificado para concorrer ao cargo de Líder Honorário de Ginásio!",
		text_id = "#C0x5B545B#Anda telah #C0x5C9970#menempati #C0x5B545B#server %s. Selamat!#C0x5C9970# Anda sekarang memenuhi syarat untuk bersaing memperebutkan posisi Honorary Gym Leader!",
		text_kr = "#C0x5B545B#당신은 #C0x5C9970#점유 #C0x5B545B#서버 %s을(를) 차지했습니다. 축하드립니다!#C0x5C9970# 이제 명예체육관장 자리에 도전하실 자격이 되셨습니다!",
		text_th = "#C0x5B545B#คุณ #C0x5C9970#ครอบครอง #C0x5B545B#เซิร์ฟเวอร์ %s ยินดีด้วย!#C0x5C9970# ตอนนี้คุณมีคุณสมบัติที่จะเข้าแข่งขันตำแหน่งผู้นำยิมกิตติมศักดิ์แล้ว!",
		text_es = "#C0x5B545B#Tienes #C0x5C9970#ocupado #C0x5B545B#servidor %s. ¡Felicitaciones! #C0x5C9970# ¡Ahora estás calificado para competir por el puesto de Líder de gimnasio honorario!",
		text = "#C0x5B545B#You've #C0x5C9970#occupied #C0x5B545B#server %s. Congratulations!#C0x5C9970# You are now qualified to compete for the position of Honorary Gym Leader!",
		id = 7936
	},
	[7937] = {
		text_en = "#C0x5B545B#You've #C0xE79900#successfully defeated #C0x5B545B#Gym Leader of %s. Congratulations!#C0x5C9970# You are now qualified to compete for the position of Honorary Gym Leader!",
		key = "gymLeaderWin",
		text_vn = "#C0x5B545B#Você #C0xE79900#derrotou com sucesso #C0x5B545B#líder do ginásio de %s. Parabéns!#C0x5C9970# Agora você está qualificado para concorrer ao cargo de Líder Honorário de Ginásio!",
