	[7986] = {
		text_en = "#C0x5B545B#Spend %d#Icommon/icon/icon_diamond.png-56-56# to reset Accessory Awaken level\n(Awaken Potential included) to the initial state. Continue?",
		key = "equipAwakeAbilityDownCost",
		text_vn = "#C0x5B545B#Gaste %d#Icommon/icon/icon_diamond.png-56-56# para redefinir o nível de Despertar de Acessório\n(Potencial de Despertar incluído) para o estado inicial. Continuar?",
		text_id = "#C0x5B545B#Belanjakan %d#Icommon/icon/icon_diamond.png-56-56# untuk mereset level Aksesori Awaken\n(termasuk Potensi Awaken) ke kondisi awal. Melanjutkan?",
		text_kr = "#C0x5B545B#액세서리 각성 레벨\n(잠재력 각성 포함)을 초기 상태로 재설정하려면 %d#Icommon/icon/icon_diamond.png-56-56#을 소비하세요. 계속하다?",
		text_th = "#C0x5B545B#ใช้จ่าย %d#Icommon/icon/icon_diamond.png-56-56# เพื่อรีเซ็ตระดับการปลุกพลังของเครื่องประดับ\n(รวมศักยภาพในการปลุกพลังด้วย) เป็นสถานะเริ่มต้น ดำเนินการต่อ?",
		text_es = "#C0x5B545B#Gasta %d#Icommon/icon/icon_diamond.png-56-56# para restablecer el nivel de despertar del accesorio\n(potencial de despertar incluido) al estado inicial. ¿Continuar?",
