	[8106] = {
		text_en = "Spend Diamonds to increase the rebate rate! \nSpend more for a higher rate as well as extra rewards!",
		key = "rmbRewardTips",
		text_vn = "Gaste diamantes para aumentar a taxa de desconto! \nGaste mais por uma tarifa mais alta e por recompensas extras!",
		text_id = "Habiskan diamond untuk meningkatkan rebate rate! \nBelanjakan lebih banyak untuk mendapatkan tarif lebih tinggi serta hadiah ekstra!",
		text_kr = "다이아몬드를 사용하여 리베이트율을 높이세요! \n더 높은 가격과 추가 보상을 위해 더 많이 지출하세요!",
		text_th = "ใช้เพชรเพื่อเพิ่มอัตราการคืนเงิน! \nใช้จ่ายมากขึ้นเพื่อรับอัตราที่สูงขึ้นและรางวัลพิเศษ!",
		text_es = "¡Gasta diamantes para aumentar la tasa de reembolso! \n¡Gasta más para obtener una tarifa más alta y recompensas adicionales!",
		text = "Spend Diamonds to increase the rebate rate! \nSpend more for a higher rate as well as extra rewards!",
		id = 8106
	},
	[8107] = {
		text_en = "Spend Diamonds to enjoy a rebate!\nSpend more for a bigger rebate as well as extra rewards!",
		key = "rmbRewardFixTips",
		text_vn = "Gaste diamantes para aproveitar um desconto!\nGaste mais para obter um desconto maior e recompensas extras!",
		text_id = "Belanjakan diamond untuk menikmati rebate!\nBelanjakan lebih banyak untuk mendapatkan rebate lebih besar serta hadiah ekstra!",
		text_kr = "다이아몬드를 사용하여 리베이트를 받으세요!\n더 많은 리베이트와 추가 보상을 받으려면 더 많이 지출하세요!",
		text_th = "ใช้เพชรเพื่อเพลิดเพลินกับส่วนลด!\nใช้จ่ายมากขึ้นเพื่อรับส่วนลดที่มากขึ้นรวมถึงรางวัลพิเศษอีกด้วย!",
		text_es = "¡Gasta diamantes para disfrutar de un reembolso!\n¡Gasta más para obtener un reembolso mayor y recompensas adicionales!",
		text = "Spend Diamonds to enjoy a rebate!\nSpend more for a bigger rebate as well as extra rewards!",
		id = 8107
	},
	[8108] = {
		text_en = "Event has ended.\nRebate will not be granted for more Diamonds consumed. Come and claim your rebate in time!",
		key = "rmbRewardEndTips",
		text_vn = "O evento terminou.\nO desconto não será concedido para mais Diamantes consumidos. Venha reivindicar seu desconto na hora certa!",
		text_id = "Event telah berakhir.\nRebate tidak akan diberikan untuk lebih banyak diamond yang dikonsumsi. Datang dan klaim rebate Anda tepat waktu!",
		text_kr = "이벤트가 종료되었습니다.\n더 이상 소비된 다이아몬드에 대해서는 리베이트가 부여되지 않습니다. 시간 내에 오셔서 리베이트를 청구하세요!",
		text_th = "กิจกรรมสิ้นสุดแล้ว\nจะไม่มีการคืนเงินหากใช้เพชรเพิ่ม มาและรับเงินคืนของคุณทันเวลา!",
		text_es = "El evento ha finalizado.\nNo se otorgará reembolso por más diamantes consumidos. ¡Ven y reclama tu reembolso a tiempo!",
		text = "Event has ended.\nRebate will not be granted for more Diamonds consumed. Come and claim your rebate in time!",
		id = 8108
	},
