	[8261] = {
		text_en = "Dear trainer, please don't believe in any advertising information such as recharge discounts on World Channels, and be wary of the behavior of buying accounts in private chats. These are all online scams! If you encounter any suspicious information, please feel free to contact customer service for feedback, wish you enjoy our game!",
		key = "preventFraudChatTips",
		text_vn = "Caro treinador, por favor, não acredite em nenhuma informação publicitária, como descontos em recargas nos Canais Mundiais, e tenha cuidado com o comportamento de comprar contas em chats privados. Tudo isso são golpes online! Se você encontrar alguma informação suspeita, não hesite em entrar em contato com o atendimento ao cliente para obter feedback, desejo que você aproveite nosso jogo!",
		text_id = "Trainer yang terhormat, mohon jangan percaya pada informasi iklan apa pun seperti diskon isi ulang di channel Dunia, dan berhati-hatilah terhadap perilaku membeli akun di obrolan pribadi. Ini semua adalah penipuan online! Jika Anda mene andakan informasi yang mencurigakan, jangan ragu untuk menghubungi layanan pelanggan untuk mendapatkan umpan balik, semoga Anda menikmati permainan kami!",
		text_kr = "트레이너 여러분, 월드 채널의 충전 할인과 같은 광고 정보를 믿지 마시고 비공개 채팅에서 계정을 구매하는 행위에 주의하시기 바랍니다. 이것들은 모두 온라인 사기입니다! 의심스러운 정보를 발견한 경우 언제든지 고객 서비스에 문의하여 피드백을 받으시기 바랍니다. 게임을 즐기시기 바랍니다!",
		text_th = "เรียนเทรนเนอร์ โปรดอย่าเชื่อข้อมูลโฆษณาใดๆ เช่น ส่วนลดการเติมเงินในช่อง World Channels และระวังพฤติกรรมการซื้อบัญชีในการแชทส่วนตัว ทั้งหมดนี้ล้วนเป็นการหลอกลวงออนไลน์! หากคุณพบข้อมูลที่น่าสงสัย โปรดติดต่อฝ่ายบริการลูกค้าเพื่อขอข้อเสนอแนะ หวังว่าคุณจะสนุกกับเกมของเรา!",
		text_es = "Estimado entrenador, no crea en ninguna información publicitaria, como descuentos de recarga en World Channels, y tenga cuidado con el comportamiento de compra de cuentas en chats privados. ¡Todas estas son estafas en línea! Si encuentra alguna información sospechosa, no dude en comunicarse con el servicio de atención al cliente para obtener comentarios. ¡Le deseamos que disfrute de nuestro juego!",
		text = "Dear trainer, please don't believe in any advertising information such as recharge discounts on World Channels, and be wary of the behavior of buying accounts in private chats. These are all online scams! If you encounter any suspicious information, please feel free to contact customer service for feedback, wish you enjoy our game!",
		id = 8261
	},
	[8262] = {
		text_en = "#Pfont/youmi1.ttf#Be vigilant and beware of account fraud",
		key = "preventFraudPosterTitle",
		text_vn = "#Pfont/youmi1.ttf#Esteja atento e tome cuidado com fraudes em contas",
		text_id = "#Pfont/youmi1.ttf#Waspada dan waspada terhadap penipuan akun",
		text_kr = "#Pfont/youmi1.ttf#계정 사기에 주의하고 조심하세요",
		text_th = "#Pfont/youmi1.ttf#ระมัดระวังและระวังการฉ้อโกงบัญชี",
		text_es = "#Pfont/youmi1.ttf#Esté atento y tenga cuidado con el fraude de cuentas",
		text = "#Pfont/youmi1.ttf#Be vigilant and beware of account fraud",
		id = 8262
	},
	[8263] = {
		text_en = [[
#Pfont/youmi1.ttf#Usage:
#Pfont/youmi.ttf#PM you and want to buy our account, but without using the formal platform! 
Price is falsely high, with the intent to lure a deal! 
Trading cash withdrawal, but also cheating fees!]],
		key = "preventFraudPosterDes1",
		text_vn = [[
#Pfont/youmi1.ttf#Uso:
#Pfont/youmi.ttf#Mande uma mensagem para você e queira comprar nossa conta, mas sem usar a plataforma formal! 
O preço está falsamente alto, com a intenção de atrair um acordo! 
Negociação de retirada de dinheiro, mas também taxas de trapaça!]],
		text_id = [[
#Pfont/youmi1.ttf#Penggunaan:
#Pfont/youmi.ttf#PM Anda dan ingin membeli akun kami, tetapi tanpa menggunakan platform formal! 
Harganya terlalu tinggi, dengan tujuan untuk mendapatkan kesepakatan! 
Perdagangan penarikan tunai, tetapi juga biaya kecurangan!]],
		text_kr = [[
#Pfont/youmi1.ttf#사용법:
#Pfont/youmi.ttf#저희 계정을 구매하고 싶지만 공식 플랫폼을 사용하지 않고 오후 1시! 
거래를 유도하려는 의도로 가격이 너무 높습니다! 
현금 인출 거래와 부정행위 수수료도 발생합니다!]],
		text_th = [[
#Pfont/youmi1.ttf#การใช้งาน:
#Pfont/youmi.ttf#PM คุณและต้องการซื้อบัญชีของเรา แต่ไม่ได้ใช้แพลตฟอร์มอย่างเป็นทางการ! 
ราคาสูงเกินจริง โดยมีจุดประสงค์เพื่อล่อลวงข้อตกลง! 
การซื้อขายถอนเงินสด แต่ยังมีค่าธรรมเนียมการโกง!]],
		text_es = [[
#Pfont/youmi1.ttf#Uso:
#Pfont/youmi.ttf#Envíale un mensaje privado y quieres comprar nuestra cuenta, ¡pero sin usar la plataforma formal! 
¡El precio es falsamente alto, con la intención de conseguir un trato! 
¡Retiro de efectivo comercial, pero también tarifas por trampa!]],
		text = [[
#Pfont/youmi1.ttf#Usage:
#Pfont/youmi.ttf#PM you and want to buy our account, but without using the formal platform! 
Price is falsely high, with the intent to lure a deal! 
Trading cash withdrawal, but also cheating fees!]],
		id = 8263
	},
	[8264] = {
		text_en = [[
#Pfont/youmi1.ttf#Friendly reminder:
#Pfont/youmi.ttf#Don’t share accounts! 
Don't share order screenshots! 
Don't unbind you phone easily! 
Please go to the formal platform for trading!]],
		key = "preventFraudPosterDes2",
		text_vn = [[
#Pfont/youmi1.ttf#Lembrete amigável:
#Pfont/youmi.ttf#Não compartilhe contas! 
Não compartilhe capturas de tela de pedidos! 
Não desvincule seu telefone facilmente! 
Por favor, vá para a plataforma formal de negociação!]],
		text_id = [[
#Pfont/youmi1.ttf#Pengingat ramah:
#Pfont/youmi.ttf#Jangan berbagi akun! 
Jangan bagikan tangkapan layar pesanan! 
Jangan melepaskan ikatan ponsel Anda dengan  andadah! 
Silakan buka platform formal untuk berdagang!]],
		text_kr = [[
#Pfont/youmi1.ttf#알림:
#Pfont/youmi.ttf#계정을 공유하지 마세요! 
주문 스크린샷을 공유하지 마세요! 
휴대전화를 쉽게 연결 해제하지 마세요! 
거래를 위해서는 공식 플랫폼으로 이동해주세요!]],
		text_th = [[
#Pfont/youmi1.ttf#คำเตือนที่เป็นมิตร:
#Pfont/youmi.ttf#อย่าแชร์บัญชี! 
อย่าแชร์ภาพหน้าจอคำสั่งซื้อ! 
อย่าปลดสายโทรศัพท์ของคุณออกง่ายๆ! 
โปรดไปที่แพลตฟอร์มอย่างเป็นทางการสำหรับการซื้อขาย!]],
		text_es = [[
#Pfont/youmi1.ttf#Recordatorio amistoso:
#Pfont/youmi.ttf#¡No compartas cuentas! 
¡No compartas capturas de pantalla de pedidos! 
¡No desvincules tu teléfono fácilmente! 
¡Por favor vaya a la plataforma formal para operar!]],
		text = [[
#Pfont/youmi1.ttf#Friendly reminder:
#Pfont/youmi.ttf#Don’t share accounts! 
Don't share order screenshots! 
Don't unbind you phone easily! 
Please go to the formal platform for trading!]],
		id = 8264
	},
