	[8486] = {
		text_en = "#C0xF76B45#Long press the #C0x5B545B# charge button, the ball can be hit higher and farther, and power will gradually weaken after release",
		key = "volleyballGuide4",
		text_vn = "#C0xF76B45#Pressione e segure o botão de carga #C0x5B545B#, a bola pode ser atingida mais alto e mais longe, e a força enfraquecerá gradualmente após o lançamento",
		text_id = "#C0xF76B45#Tekan lama tombol #C0x5B545B# ​​isi daya, bola dapat dipukul lebih tinggi dan lebih jauh, dan kekuatan secara berStage akan melemah setelah dilepaskan",
		text_kr = "#C0xF76B45# #C0x5B545B# 충전 버튼을 길게 누르면 공이 더 높이, 더 멀리 날아갈 수 있으며, 놓으면 힘이 점차 약해집니다.",
		text_th = "#C0xF76B45#กดปุ่มชาร์จ #C0x5B545B# ค้างไว้ ลูกบอลสามารถตีได้สูงขึ้นเรื่อยๆ และพลังจะค่อยๆ ลดลงหลังจากปล่อย",
		text_es = "#C0xF76B45# Mantenga presionado el botón de carga #C0x5B545B#, la pelota se puede golpear más y más lejos, y la potencia se debilitará gradualmente después del lanzamiento.",
		text = "#C0xF76B45#Long press the #C0x5B545B# charge button, the ball can be hit higher and farther, and power will gradually weaken after release",
		id = 8486
	},
	[8487] = {
		text_en = "Every time #C0xF76B45# hits back #C0x5B545B# successfully, it will accumulate stamina. When stamina reaches certain amount can release skills, please use it reasonably",
		key = "volleyballGuide5",
		text_vn = "Cada vez que #C0xF76B45# responder #C0x5B545B# com sucesso, ele acumulará resistência. Quando a resistência atinge certa quantidade pode liberar habilidades, por favor use-a razoavelmente",
		text_id = "Setiap kali #C0xF76B45# berhasil membalas #C0x5B545B#, stamina akan terakumulasi. Ketika stamina mencapai jumlah tertentu dapat melepaskan Skill, harap gunakan secara wajar",
		text_kr = "#C0xF76B45#가 반격 #C0x5B545B#에 성공할 때마다 체력이 축적됩니다. 체력이 일정 수준에 도달하면 스킬이 해제될 수 있으므로 합리적으로 사용하시기 바랍니다.",
		text_th = "ทุกครั้งที่ #C0xF76B45# ตีกลับ #C0x5B545B# ได้สำเร็จ มันจะสะสมความแข็งแกร่ง เมื่อความแข็งแกร่งถึงจำนวนหนึ่งสามารถปลดปล่อยทักษะได้ โปรดใช้มันอย่างสมเหตุสมผล",
		text_es = "Cada vez que #C0xF76B45# devuelve el golpe a #C0x5B545B# con éxito, acumulará resistencia. Cuando la resistencia alcanza cierta cantidad puede liberar habilidades, úsala de manera razonable.",
		text = "Every time #C0xF76B45# hits back #C0x5B545B# successfully, it will accumulate stamina. When stamina reaches certain amount can release skills, please use it reasonably",
