	[8514] = {
		text_en = "#C0x5B545B#[Jump Hit]\n The ball will fly farther",
		key = "volleyballSkill1",
		text_vn = "#C0x5B545B#[Jump Hit]\n A bola voará mais longe",
		text_id = "#C0x5B545B#[Jump Hit]\n Bola akan terbang lebih jauh",
		text_kr = "#C0x5B545B#[Jump Hit]\n 공이 더 멀리 날아갈 거예요",
		text_th = "#C0x5B545B#[Jump Hit]\n ลูกบอลจะบินได้ไกลขึ้น",
		text_es = "#C0x5B545B#[Jump Hit]\n La pelota volará más lejos",
		text = "#C0x5B545B#[Jump Hit]\n The ball will fly farther",
		id = 8514
	},
	[8515] = {
		text_en = "#C0x5B545B#[Charge Ball]\n Although you can’t take off when you charging, your movement speed slows down, but the longer you charge up, the more powerful the ball will be.",
		key = "volleyballSkill2",
		text_vn = "#C0x5B545B#[Charge Ball]\n Embora você não possa decolar durante o carregamento, sua velocidade de movimento diminui, mas quanto mais você carregar, mais poderosa será a bola.",
		text_id = "#C0x5B545B#[Charge Ball]\n Meski anda tidak bisa lepas landas saat mengisi daya, kecepatan gerakan anda melambat, namun semakin lama anda mengisi daya, semakin kuat bolanya.",
		text_kr = "#C0x5B545B#[Charge Ball]\n 돌진 중에는 이륙할 수 없지만 이동 속도가 느려지지만, 돌진 시간이 길어질수록 공의 위력은 더욱 강력해집니다.",
		text_th = "#C0x5B545B#[Charge Ball]\n แม้ว่าคุณจะไม่สามารถถอดออกได้เมื่อชาร์จ แต่ความเร็วในการเคลื่อนที่ของคุณจะช้าลง แต่ยิ่งคุณชาร์จนานขึ้น ลูกบอลก็จะยิ่งมีพลังมากขึ้นเท่านั้น",
		text_es = "#C0x5B545B#[Charge Ball]\n Aunque no puedes despegar cuando cargas, tu velocidad de movimiento se ralentiza, pero cuanto más cargues, más poderosa será la pelota.",
		text = "#C0x5B545B#[Charge Ball]\n Although you can’t take off when you charging, your movement speed slows down, but the longer you charge up, the more powerful the ball will be.",
		id = 8515
	},
	[8516] = {
		text_en = "#C0x5B545B#[Skill Ball]\n After successfully hitting back the opponent's ball, 1 point of stamina will be accumulated. When there is no stamina,\n skills are not available",
		key = "volleyballSkill3",
		text_vn = "#C0x5B545B#[Skill Ball]\n Depois de rebater com sucesso a bola do adversário, 1 ponto de resistência será acumulado. Quando não há resistência,\n habilidades não estão disponíveis",
		text_id = "#C0x5B545B#[Skill Ball]\n Setelah berhasil memukul balik bola lawan, 1 poin stamina akan diakumulasikan. Jika tidak ada stamina,\n Skill tidak tersedia",
		text_kr = "#C0x5B545B#[Skill Ball]\n 상대방의 공을 성공적으로 맞힌 후 체력이 1포인트 적립됩니다. 체력이 없으면\n 스킬을 사용할 수 없습니다.",
		text_th = "#C0x5B545B#[Skill Ball]\n หลังจากตีกลับลูกบอลของฝ่ายตรงข้ามได้สำเร็จ จะสะสม 1 คะแนน เมื่อไม่มีความแข็งแกร่ง\n ทักษะจะไม่พร้อมใช้งาน",
		text_es = "#C0x5B545B#[Skill Ball]\n Después de devolver con éxito la pelota del oponente, se acumulará 1 punto de resistencia. Cuando no hay resistencia,\n las habilidades no están disponibles",
		text = "#C0x5B545B#[Skill Ball]\n After successfully hitting back the opponent's ball, 1 point of stamina will be accumulated. When there is no stamina,\n skills are not available",
		id = 8516
	},
	[8517] = {
		text_en = "#C0x5B545B#[Skill Ball]\n After 3 points of stamina, you can release First Gear skill at any time. After using it, your ball will be added a attribute slow down, and it will slow down opponent when they touch it.",
		key = "volleyballSkill4",
		text_vn = "#C0x5B545B#[Skill Ball]\n Após 3 pontos de resistência, você pode liberar a habilidade First Gear a qualquer momento. Depois de usá-la, sua bola receberá um atributo de desaceleração, e isso irá desacelerar o oponente quando ele tocá-la.",
		text_id = "#C0x5B545B#[Skill Ball]\n Setelah 3 poin stamina, Anda dapat melepaskan skill First Gear kapan saja. Setelah menggunakannya, bola Anda akan ditambahkan atribut slowdown, dan akan memperlambat lawan saat mereka menyentuhnya.",
		text_kr = "#C0x5B545B#[Skill Ball]\n 체력 3포인트 이후 언제든지 퍼스트 기어 스킬을 해제할 수 있습니다. 사용 후에는 공에 속도 저하 속성이 추가되고 상대가 공에 닿으면 속도가 느려집니다.",
		text_th = "#C0x5B545B#[Skill Ball]\n หลังจาก 3 คะแนน คุณสามารถปล่อยทักษะเกียร์แรกได้ตลอดเวลา หลังจากใช้งาน ลูกบอลของคุณจะถูกเพิ่มคุณสมบัติทำให้ช้าลง และจะทำให้คู่ต่อสู้ช้าลงเมื่อพวกเขาสัมผัสมัน",
		text_es = "#C0x5B545B#[Skill Ball]\n Después de 3 puntos de resistencia, puedes liberar la habilidad First Gear en cualquier momento. Después de usarlo, a tu bola se le agregará un atributo de ralentización y ralentizará al oponente cuando la toque.",
		text = "#C0x5B545B#[Skill Ball]\n After 3 points of stamina, you can release First Gear skill at any time. After using it, your ball will be added a attribute slow down, and it will slow down opponent when they touch it.",
		id = 8517
	},
	[8518] = {
		text_en = "#C0x5B545B#[Skill Ball]\n After 6 points of stamina, the Second Gear skill can be released at any time. After use, your ball will have an attribute attack, which will be unstoppable! \n After using the skill, stamina will be consumed, please pay attention to the timing of use",
		key = "volleyballSkill5",
		text_vn = "#C0x5B545B#[Skill Ball]\n Após 6 pontos de resistência, a habilidade Segunda Marcha pode ser liberada a qualquer momento. Após o uso, sua bola terá um ataque de atributo, que será imparável! \n Depois de usar a habilidade, a resistência será consumida, preste atenção ao tempo de uso",
		text_id = "#C0x5B545B#[Skill Ball]\n Setelah 6 poin stamina, skill Second Gear dapat dilepaskan kapan saja. Setelah digunakan, bola Anda akan memiliki serangan atribut yang tidak dapat dihentikan! \n Setelah menggunakan skill, stamina akan terkuras, harap perhatikan waktu penggunaan",
		text_kr = "#C0x5B545B#[Skill Ball]\n 체력 6포인트 이후에는 언제든지 두 번째 기어 스킬을 사용할 수 있습니다. 사용 후에는 공에 속성 공격이 적용되어 막을 수 없습니다! \n 스킬 사용 후 체력이 소모되오니 사용 타이밍에 주의해주세요.",
		text_th = "#C0x5B545B#[Skill Ball]\n หลังจาก 6 แต้มของความแข็งแกร่ง ทักษะเกียร์สองสามารถปล่อยออกมาได้ตลอดเวลา หลังการใช้งาน ลูกบอลของคุณจะถูกโจมตีด้วยคุณสมบัติซึ่งจะไม่มีใครหยุดยั้งได้! \n หลังจากใช้ทักษะ ค่าความแข็งแกร่งจะถูกใช้ โปรดใส่ใจกับจังหวะการใช้งาน",
		text_es = "#C0x5B545B#[Skill Ball]\n Después de 6 puntos de resistencia, la habilidad Second Gear se puede liberar en cualquier momento. Después de su uso, tu bola tendrá un atributo de ataque, ¡que será imparable! \n Después de usar la habilidad, se consumirá resistencia, preste atención al momento de uso",
		text = "#C0x5B545B#[Skill Ball]\n After 6 points of stamina, the Second Gear skill can be released at any time. After use, your ball will have an attribute attack, which will be unstoppable! \n After using the skill, stamina will be consumed, please pay attention to the timing of use",
		id = 8518
	},
