	[8602] = {
		text_en = "#C0x5B545B# You only got one betting chance in each battle group, do you confirm to consume %d#Icommon/icon/icon_ghb.png-56-56# and bet on this Union?",
		key = "preliminaryMatchTip",
		text_vn = "#C0x5B545B# Você só tem uma chance de aposta em cada grupo de batalha, confirma consumir %d#Icommon/icon/icon_ghb.png-56-56# e aposta nessa União?",
		text_id = "#C0x5B545B# Anda hanya mendapat satu kesempatan taruhan di setiap grup pertarungan, apakah Anda mengonfirmasi untuk menggunakan %d#Icommon/icon/icon_ghb.png-56-56# dan bertaruh pada Serikat ini?",
		text_kr = "#C0x5B545B# 각 배틀 그룹에서 베팅 기회는 단 한 번뿐입니다. %d#Icommon/icon/icon_ghb.png-56-56#을 소비하고 이 유니온에 베팅하시겠습니까?",
		text_th = "#C0x5B545B# คุณมีโอกาสเดิมพันเพียงครั้งเดียวในแต่ละกลุ่มการรบ คุณยืนยันที่จะบริโภค %d#Icommon/icon/icon_ghb.png-56-56# และเดิมพันกับสหภาพนี้หรือไม่?",
		text_es = "#C0x5B545B# Solo tienes una oportunidad de apostar en cada grupo de batalla, ¿confirmas consumir %d#Icommon/icon/icon_ghb.png-56-56# y apostar en esta Unión?",
		text = "#C0x5B545B# You only got one betting chance in each battle group, do you confirm to consume %d#Icommon/icon/icon_ghb.png-56-56# and bet on this Union?",
		id = 8602
	},
	[8603] = {
		text_en = "#C0x5B545B#You only got one betting chance on finals, do you confirm to consume %d#Icommon/icon/icon_ghb.png-56-56# Union coins to bet on this Union?",
		key = "finalMatchTip",
		text_vn = "#C0x5B545B#Você só tem uma chance de aposta nas finais, você confirma consumir %d#Icommon/icon/icon_ghb.png-56-56# Union coins para apostar nesta Union?",
		text_id = "#C0x5B545B#Anda hanya mendapat satu kesempatan taruhan di final, apakah Anda mengonfirmasi untuk menggunakan %d#Icommon/icon/icon_ghb.png-56-56# koin Union untuk bertaruh pada Union ini?",
		text_kr = "#C0x5B545B#결승전 배팅 기회는 단 한 번밖에 없습니다. %d#Icommon/icon/icon_ghb.png-56-56# 이 유니온에 베팅할 유니온 코인을 소비하시겠습니까?",
		text_th = "#C0x5B545B#คุณมีโอกาสเดิมพันเพียงครั้งเดียวในรอบชิงชนะเลิศ คุณยืนยันที่จะใช้ %d#Icommon/icon/icon_ghb.png-56-56# เหรียญยูเนี่ยนเพื่อเดิมพันในยูเนี่ยนนี้หรือไม่?",
		text_es = "#C0x5B545B#Solo tienes una oportunidad de apostar en las finales, ¿confirmas consumir %d#Icommon/icon/icon_ghb.png-56-56# monedas de la Unión para apostar en esta Unión?",
		text = "#C0x5B545B#You only got one betting chance on finals, do you confirm to consume %d#Icommon/icon/icon_ghb.png-56-56# Union coins to bet on this Union?",
