	[9152] = {
		text_en = "#C0x67A07A#%s#C0x5B545B#is throwing a#C0x%s#%s#C0x5B545B# party, can gain the Party Effect: Immediately restore %s Pokémon's %s  energy, and get Homeland Coin, Homeland material and some random resource rewards. No time to explain, come on!#LULparty##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		key = "partyInformationDesc",
		text_vn = "#C0x67A07A#%s#C0x5B545B#está dando uma festa#C0x%s#%s#C0x5B545B#, pode ganhar o efeito de festa: restaurar imediatamente a energia de %s Pokémon e obter Moeda da Pátria, material da Pátria e algumas recompensas de recursos aleatórios. Não há tempo para explicar, vamos lá!#LULparty##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_id = "#C0x67A07A#%s#C0x5B545B#sedang mengadakan Party#C0x%s#%s#C0x5B545B#, dapat memperoleh Efek Party: Segera pulihkan energi %s Pokémon %s, dan dapatkan Koin Homeland, materi Homeland, dan beberapa hadiah sumber daya acak. Tidak ada waktu untuk menjelaskan, ayolah!#LULparty##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_kr = "#C0x67A07A#%s#C0x5B545B#가 #C0x%s#%s#C0x5B545B# 파티를 열고 있습니다. 파티 효과를 얻을 수 있습니다: %s 포켓몬의 %s 에너지를 즉시 복원하고 홈랜드 코인, 홈랜드 재료 및 일부 무작위 자원 보상을 받으세요. 설명할 시간도 없이 어서!#LULparty##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_th = "#C0x67A07A#%s#C0x5B545B# กำลังจัดปาร์ตี้#C0x%s#%s#C0x5B545B# สามารถรับเอฟเฟกต์ปาร์ตี้ได้: ฟื้นฟูพลังงาน %s ของโปเกมอน %s ทันที และรับเหรียญแห่งบ้านเกิด วัสดุแห่งบ้านเกิด และรางวัลทรัพยากรแบบสุ่มบางส่วน ไม่มีเวลาอธิบาย เอาน่า!#LULparty##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text_es = "#C0x67A07A#%s#C0x5B545B#está organizando una#C0x%s#%s#C0x5B545B#, puede obtener el efecto de fiesta: restaurar inmediatamente la energía de %s Pokémon y obtener monedas de Homeland, material de Homeland y algunas recompensas de recursos aleatorios. No hay tiempo para explicar, ¡vamos! #LULparty##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		text = "#C0x67A07A#%s#C0x5B545B#is throwing a#C0x%s#%s#C0x5B545B# party, can gain the Party Effect: Immediately restore %s Pokémon's %s  energy, and get Homeland Coin, Homeland material and some random resource rewards. No time to explain, come on!#LULparty##Icity/adventure/clone_battle/imag_ljjr.png-182-54#",
		id = 9152
	},
	[9153] = {
		text_en = "#C0x5B545B#The Party Effect in this party: #C0xF76B45#Pokémon quickly restore energy effect is not used up#C0x5B545B#. After going to other parties#C0xF76B45#the party effect in this party will become invalid#C0x5B545B#. Do you still go to other parties?",
		key = "partyEffectUnusedTips",
		text_vn = "#C0x5B545B#O efeito de festa nesta festa: #C0xF76B45#Pokémon restaura rapidamente o efeito de energia e não se esgota#C0x5B545B#. Depois de ir para outras festas#C0xF76B45#o efeito festa nesta festa se tornará inválido#C0x5B545B#. Você ainda vai a outras festas?",
		text_id = "#C0x5B545B#Efek Party di Party ini: #C0xF76B45#Pokémon dengan cepat memulihkan efek energi yang tidak habis#C0x5B545B#. Setelah pergi ke party lain#C0xF76B45#efek party di party ini menjadi tidak valid#C0x5B545B#. Apakah Anda masih pergi ke Party lain?",
		text_kr = "#C0x5B545B#이 파티의 파티 효과: #C0xF76B45#포켓몬의 기력 급속 회복 효과는 소모되지 않습니다#C0x5B545B#. 다른 파티에 가면#C0xF76B45#이 파티의 파티 효과는 무효화됩니다#C0x5B545B#. 아직도 다른 파티에 가시나요?",
		text_th = "#C0x5B545B#เอฟเฟกต์ปาร์ตี้ในปาร์ตี้นี้: #C0xF76B45#เอฟเฟกต์โปเกมอนฟื้นฟูพลังงานอย่างรวดเร็วไม่หมด#C0x5B545B# หลังจากไปปาร์ตี้อื่น#C0xF76B45#เอฟเฟกต์ปาร์ตี้ในปาร์ตี้นี้จะไม่ถูกต้อง#C0x5B545B# คุณยังไปปาร์ตี้อื่นอยู่ไหม?",
		text_es = "#C0x5B545B#El efecto de fiesta en esta fiesta: #C0xF76B45#Los Pokémon restauran rápidamente el efecto de energía y no se agotan#C0x5B545B#. Después de ir a otras fiestas#C0xF76B45#el efecto de fiesta en esta fiesta dejará de ser válido#C0x5B545B#. ¿Sigues yendo a otras fiestas?",
		text = "#C0x5B545B#The Party Effect in this party: #C0xF76B45#Pokémon quickly restore energy effect is not used up#C0x5B545B#. After going to other parties#C0xF76B45#the party effect in this party will become invalid#C0x5B545B#. Do you still go to other parties?",
		id = 9153
	},
