	[9183] = {
		text_en = "#C0x5B545B#We have received your feedback. In order to solve your problems quickly, please contact our official Facebook customer service [Pocket Trial] to express your problems and we will help you. (Working time: 9:00-21:30)",
		key = "issueFeedback",
		text_vn = "#C0x5B545B#Recebemos seu feedback. Para resolver seus problemas rapidamente, entre em contato com nosso atendimento oficial do Facebook [Pocket Trial] para expressar seus problemas e nós o ajudaremos. (Horário de trabalho: 9h00-21h30)",
		text_id = "#C0x5B545B#Kami telah menerima tanggapan Anda. Untuk menyelesaikan masalah Anda dengan cepat, silakan hubungi layanan pelanggan Facebook resmi kami [Pocket Trial] untuk mengungkapkan masalah Anda dan kami akan membantu Anda. (Waktu kerja: 9:00-21:30)",
		text_kr = "#C0x5B545B#여러분의 피드백을 받았습니다. 빠른 문제 해결을 위해 공식 페이스북 고객센터로 연락주세요[Pocket Trial] 문제를 알려주시면 도와드리겠습니다. (근무시간: 9:00-21:30)",
		text_th = "#C0x5B545B#เราได้รับคำติชมของคุณแล้ว เพื่อที่จะแก้ไขปัญหาของคุณได้อย่างรวดเร็ว โปรดติดต่อฝ่ายบริการลูกค้า Facebook อย่างเป็นทางการของเรา [Pocket Trial] เพื่อแสดงปัญหาของคุณ แล้วเราจะช่วยคุณ (เวลาทำการ: 9:00-21:30 น.)",
		text_es = "#C0x5B545B#Hemos recibido tus comentarios. Para resolver tus problemas rápidamente, por favor contacta con nuestro servicio de atención al cliente oficial de Facebook [Pocket Trial] para expresar tus problemas y te ayudaremos. (Horario de trabajo: 9:00-21:30)",
		text = "#C0x5B545B#We have received your feedback. In order to solve your problems quickly, please contact our official Facebook customer service [Pocket Trial] to express your problems and we will help you. (Working time: 9:00-21:30)",
		id = 9183
	},
