	[9404] = {
		text_en = "#C0x5B545B#[Mysterious Guardian] \n After adding, you will get a layer of mysterious shield. Withing 10 seconds after the shield taks effect, you can be immune to all DMG",
		key = "spriteJumpProp5",
		text_vn = "#C0x5B545B#[Mysterious Guardian] \n Após adicionar, você obterá uma camada de escudo misterioso. Dentro de 10 segundos após o escudo entrar em vigor, você pode ficar imune a todos os DMG",
		text_id = "#C0x5B545B#[Mysterious Guardian] \n Setelah menambahkan, Anda akan mendapatkan lapisan perisai misterius. Dalam 10 detik setelah efek perisai tidak diterapkan, anda akan kebal terhadap semua DMG",
		text_kr = "#C0x5B545B#[Mysterious Guardian] \n 추가하고 나면 신비로운 보호막을 얻을 수 있습니다. 보호막이 적용된 후 10초 이내에 모든 피해에 면역이 됩니다.",
		text_th = "#C0x5B545B#[Mysterious Guardian] \n หลังจากเพิ่มคุณจะได้รับโล่ลึกลับหนึ่งชั้น ภายใน 10 วินาทีหลังจากที่ได้รับผลของโล่ คุณจะสามารถต้านทานความเสียหายทั้งหมดได้",
		text_es = "#C0x5B545B#[Mysterious Guardian] \n Después de agregar, obtendrás una capa de escudo misterioso. Dentro de los 10 segundos posteriores a que el escudo entre en vigor, puedes ser inmune a todos los DAÑOS.",
		text = "#C0x5B545B#[Mysterious Guardian] \n After adding, you will get a layer of mysterious shield. Withing 10 seconds after the shield taks effect, you can be immune to all DMG",
		id = 9404
	},
	[9405] = {
