	[9460] = {
		text_en = "After #C0xF76B45#Dream Bud #C0x5B545B# appearing on the screen, the button is activated. Clicking the button will lead you to the board where the Dream Bud is located",
		key = "spriteJumpGuide3",
		text_vn = "Após #C0xF76B45#Dream Bud #C0x5B545B# aparecer na tela, o botão é ativado. Clicar no botão o levará ao quadro onde o Dream Bud está localizado",
		text_id = "Setelah #C0xF76B45#Dream Bud #C0x5B545B# muncul di layar, tombol tersebut diaktifkan. Mengklik tombol tersebut akan membawa Anda ke papan tempat Dream Bud berada",
		text_kr = "화면에 #C0xF76B45#Dream Bud #C0x5B545B#가 나타난 후 버튼이 활성화됩니다. 버튼을 클릭하면 Dream Bud가 위치한 게시판으로 이동됩니다.",
		text_th = "หลังจากที่ #C0xF76B45#ดรีมบัด #C0x5B545B# ปรากฏบนหน้าจอ ปุ่มจะเปิดใช้งาน การคลิกปุ่มจะนำคุณไปยังกระดานซึ่งเป็นที่ตั้งของ Dream Bud",
		text_es = "Después de que #C0xF76B45#Dream Bud #C0x5B545B# aparezca en la pantalla, el botón se activa. Al hacer clic en el botón accederás al tablero donde se encuentra el Dream Bud.",
		text = "After #C0xF76B45#Dream Bud #C0x5B545B# appearing on the screen, the button is activated. Clicking the button will lead you to the board where the Dream Bud is located",
		id = 9460
	},
	[9461] = {
		text_en = "The items in the gameplay have different functions, please check #C0xF76B45#rules#C0x5B545B#. The #C0xF76B45#Monster#C0x5B545B# can be stepped on #C0xF76B45#above#C0x5B545B#, and the monster which be defeated will provide #C0xF76B45#extra points !#C0x5B545B#",
		key = "spriteJumpGuide4",
		text_vn = "Os itens do jogo têm funções diferentes, verifique #C0xF76B45#regras#C0x5B545B#. O #C0xF76B45#Monstro#C0x5B545B# pode ser pisado #C0xF76B45#acima#C0x5B545B#, e o monstro que for derrotado fornecerá #C0xF76B45#pontos extras!#C0x5B545B#",
		text_id = "Item dalam gameplay memiliki fungsi yang berbeda-beda, silakan periksa #C0xF76B45#rules#C0x5B545B#. #C0xF76B45#Monster#C0x5B545B# dapat diinjak #C0xF76B45#di atas#C0x5B545B#, dan monster yang dikalahkan akan memberikan #C0xF76B45#poin tambahan !#C0x5B545B#",
		text_kr = "게임플레이에 포함된 아이템은 다양한 기능을 가지고 있으니 #C0xF76B45#규칙#C0x5B545B#을 확인해주세요. #C0xF76B45#몬스터#C0x5B545B#는 #C0xF76B45#위#C0x5B545B#를 밟을 수 있으며, 쓰러뜨린 몬스터는 #C0xF76B45#추가 포인트 !#C0x5B545B#를 제공합니다.",
		text_th = "ไอเทมในเกมมีฟังก์ชั่นที่แตกต่างกัน โปรดตรวจสอบ #C0xF76B45#กฎ#C0x5B545B# #C0xF76B45#สัตว์ประหลาด#C0x5B545B# สามารถเหยียบขึ้นไปบน #C0xF76B45#เหนือ#C0x5B545B# ได้ และสัตว์ประหลาดที่ถูกกำจัดจะให้คะแนน #C0xF76B45#คะแนนพิเศษ !#C0x5B545B#",
		text_es = "Los elementos del juego tienen diferentes funciones, consulte #C0xF76B45#reglas#C0x5B545B#. Se puede pisar al #C0xF76B45#Monstruo#C0x5B545B# #C0xF76B45#arriba#C0x5B545B#, y el monstruo que sea derrotado proporcionará #C0xF76B45#puntos extra.#C0x5B545B#",
		text = "The items in the gameplay have different functions, please check #C0xF76B45#rules#C0x5B545B#. The #C0xF76B45#Monster#C0x5B545B# can be stepped on #C0xF76B45#above#C0x5B545B#, and the monster which be defeated will provide #C0xF76B45#extra points !#C0x5B545B#",
		id = 9461
	},
	[9462] = {
		text_en = "Cabin layout and furniture rules have changed, and the system has automatically adjusted the cabin layout. Please go to check the layout of your cabin to display ranking information more accurately!",
		key = "townHomeFurnitureEmbattleHint",
		text_vn = "O layout da cabine e as regras de mobiliário mudaram e o sistema ajustou automaticamente o layout da cabine. Verifique o layout da sua cabine para exibir as informações de classificação com mais precisão!",
		text_id = "Tata letak kabin dan aturan furnitur telah berubah, dan sistem secara otomatis menyesuaikan tata letak kabin. Silakan periksa tata letak kabin Anda untuk menampilkan informasi peringkat dengan lebih akurat!",
		text_kr = "객실 레이아웃과 가구 규칙이 변경되었으며 시스템이 객실 레이아웃을 자동으로 조정했습니다. 순위 정보를 더 정확하게 표시하려면 객실 배치를 확인하세요!",
		text_th = "กฎผังห้องโดยสารและเฟอร์นิเจอร์มีการเปลี่ยนแปลง และระบบได้ปรับเค้าโครงห้องโดยสารโดยอัตโนมัติ โปรดไปตรวจสอบเค้าโครงห้องโดยสารของคุณเพื่อแสดงข้อมูลการจัดอันดับได้แม่นยำยิ่งขึ้น!",
		text_es = "Las reglas de distribución y mobiliario de la cabina han cambiado y el sistema ha ajustado automáticamente la distribución de la cabina. ¡Vaya a verificar el diseño de su cabina para mostrar la información de clasificación con mayor precisión!",
		text = "Cabin layout and furniture rules have changed, and the system has automatically adjusted the cabin layout. Please go to check the layout of your cabin to display ranking information more accurately!",
		id = 9462
	},
