	[9510] = {
		text_en = "#C0x5B545B#Confirm that #C0x5C9970#%s#C0x5B545B# and #C0x3C8B99#%s#C0x5B545B# will perform a temporary star exchange? \n#C0xF76B45# (After the exchange is over, this field will have a cooldown of %s and cannot be used, please confirm carefully)",
		key = "confirmAid",
		text_vn = "#C0x5B545B#Confirma que #C0x5C9970#%s#C0x5B545B# e #C0x3C8B99#%s#C0x5B545B# realizarão uma troca temporária de estrelas? \n#C0xF76B45# (Após o término da troca, este campo terá um tempo de espera de %s e não poderá ser utilizado, por favor confirme com atenção)",
		text_id = "#C0x5B545B#Konfirmasi bahwa #C0x5C9970#%s#C0x5B545B# dan #C0x3C8B99#%s#C0x5B545B# akan melakukan pertukaran bintang sementara? \n#C0xF76B45# (Setelah penukaran selesai, kolom ini akan memiliki cooldown %s dan tidak dapat digunakan, harap konfirmasi dengan cermat)",
		text_kr = "#C0x5B545B##C0x5C9970#%s#C0x5B545B#와 #C0x3C8B99#%s#C0x5B545B#가 임시 스타 교환을 할 것인지 확인하시겠습니까? \n#C0xF76B45# (교환이 끝나면 이 필드는 %s의 쿨타임을 갖게 되어 사용할 수 없으니 꼭 확인해 주세요)",
		text_th = "#C0x5B545B#ยืนยันว่า #C0x5C9970#%s#C0x5B545B# และ #C0x3C8B99#%s#C0x5B545B# จะทำการแลกเปลี่ยนดาวชั่วคราวใช่ไหม? \n#C0xF76B45# (หลังจากการแลกเปลี่ยนสิ้นสุดลง ช่องนี้จะมีคูลดาวน์ %s และไม่สามารถใช้งานได้ โปรดยืนยันอย่างรอบคอบ)",
		text_es = "#C0x5B545B#Confirma que #C0x5C9970#%s#C0x5B545B# y #C0x3C8B99#%s#C0x5B545B# realizarán un intercambio de estrellas temporal? \n#C0xF76B45# (Una vez finalizado el intercambio, este campo tendrá un tiempo de reutilización de %s y no se podrá utilizar; confírmelo cuidadosamente)",
		text = "#C0x5B545B#Confirm that #C0x5C9970#%s#C0x5B545B# and #C0x3C8B99#%s#C0x5B545B# will perform a temporary star exchange? \n#C0xF76B45# (After the exchange is over, this field will have a cooldown of %s and cannot be used, please confirm carefully)",
		id = 9510
	},
