	[9535] = {
		text_en = "#C0x5B545B# After the cancellation, the exchange position will be counted down to #C0xF76B45#%s #C0x5B545B#, during this period, no star-level temporary exchange is allowed, confirm the cancellation #C0x5C9970#%s#C0x5B545B# and #C0x3C8B99#%s#C0x5B545B# Temporary exchange of stars?",
