	[9548] = {
		text_en = "#F44##C0xFFFCED#Homeland skills %s → %s, energy value upper limit %s → %s, duty will be calculated according to new skills\n#F20#\n",
		key = "starHomeTown3",
		text_vn = "#F44##C0xFFFCED#Habilidades da pátria %s → %s, limite superior do valor energético %s → %s, o dever será calculado de acordo com as novas habilidades\n#F20#\n",
		text_id = "#F44##C0xFFFCED#Skill Tanah Air %s → %s, Batas atas nilai energi %s → %s, tugas akan dihitung berdasarkan Skill baru\n#F20#\n",
		text_kr = "#F44##C0xFFFCED#국토 스킬 %s → %s, 에너지 값 상한 %s → %s, 새로운 스킬에 따라 임무가 계산됩니다\n#F20#\n",
		text_th = "#F44##C0xFFFCED#ทักษะบ้านเกิด %s → %s ค่าพลังงานขีดจำกัดบน %s → %s หน้าที่จะถูกคำนวณตามทักษะใหม่\n#F20#\n",
		text_es = "#F44##C0xFFFCED#Habilidades de la patria %s → %s, valor de energía límite superior %s → %s, el deber se calculará de acuerdo con las nuevas habilidades\n#F20#\n",
		text = "#F44##C0xFFFCED#Homeland skills %s → %s, energy value upper limit %s → %s, duty will be calculated according to new skills\n#F20#\n",
		id = 9548
	},
	[9549] = {
		text_en = "#F44##C0xFFFCED# If homeland skills and stamina are not unlocked, elves on duty will directly remove the settlement output\n#F20#\n",
		key = "starHomeTown4",
		text_vn = "#F44##C0xFFFCED# Se as habilidades e resistência da terra natal não forem desbloqueadas, os elfos de plantão removerão diretamente a saída do assentamento\n#F20#\n",
		text_id = "#F44##C0xFFFCED# Jika skill tanah air dan stamina tidak terbuka, elf yang bertugas akan langsung menghapus hasil penyelesaian\n#F20#\n",
		text_kr = "#F44##C0xFFFCED# 조국 스킬과 체력이 잠금 해제되지 않으면 근무 중인 엘프가 정착지 출력을 직접 제거합니다#F20#\n",
		text_th = "#F44##C0xFFFCED# หากทักษะบ้านเกิดและความแข็งแกร่งไม่ได้รับการปลดล็อค เอลฟ์ที่ปฏิบัติหน้าที่จะลบผลลัพธ์การตั้งถิ่นฐานออกโดยตรง\n#F20#\n",
		text_es = "#F44##C0xFFFCED# Si las habilidades y la resistencia de la tierra natal no se desbloquean, los elfos de servicio eliminarán directamente la salida del asentamiento\n#F20#\n",
		text = "#F44##C0xFFFCED# If homeland skills and stamina are not unlocked, elves on duty will directly remove the settlement output\n#F20#\n",
		id = 9549
	},
